/* Term 03 additional vocabulary — semantic batch 31. */
(()=> {
 const S=window.PERSIAN_SEMANTICS||(window.PERSIAN_SEMANTICS={});
 const rows={
 "سرخک":["بیماری ویروسی و واگیرداری که معمولاً با تب و دانه‌های قرمز پوستی همراه است.","Measles; a contagious viral disease commonly associated with fever and a red skin rash.","الحصبة؛ مرض فيروسي معدٍ يصاحبه عادةً ارتفاع الحرارة وطفح جلدي أحمر."],
 "قصه‌گو":["کسی که داستان یا حکایت را برای دیگران تعریف می‌کند؛ راوی داستان.","A storyteller; someone who tells stories or tales to others.","راوي القصص؛ شخص يحكي القصص والحكايات للآخرين."],
 "تحت تأثیر قرار گرفتن":["از رفتار، سخن، رویداد یا عاملی اثر پذیرفتن و در فکر، احساس یا رفتار تغییر کردن.","To be influenced or affected by something; to experience a change in thought, feeling, or behaviour because of it.","تأثّرَ بشيء؛ تغيّر فكره أو شعوره أو سلوكه نتيجة قول أو فعل أو حدث أو عامل."],
 "نیروی فرهنگی":["توان یا عاملی که از راه ارزش‌ها، هنر، زبان، آموزش و سنت‌ها بر جامعه و رفتار مردم اثر می‌گذارد.","A cultural force; an influence arising from values, art, language, education, or traditions that shapes society and people's behaviour.","قوة ثقافية؛ تأثير ينشأ من القيم أو الفن أو اللغة أو التعليم أو التقاليد ويشكّل المجتمع وسلوك الناس."],
 "جرم‌های اینترنتی":["اعمال غیرقانونی که با استفاده از اینترنت، رایانه یا شبکه‌های دیجیتال انجام می‌شوند؛ مانند کلاهبرداری و دسترسی غیرمجاز.","Cybercrimes; illegal acts carried out using the internet, computers, or digital networks, such as fraud or unauthorised access.","الجرائم الإلكترونية؛ أفعال غير قانونية تُرتكب باستخدام الإنترنت أو الحاسوب أو الشبكات الرقمية، مثل الاحتيال أو الدخول غير المصرّح به."],
 "سایت‌های غیراخلاقی":["وب‌سایت‌هایی که محتوای مغایر با معیارهای اخلاقی یا قوانین یک جامعه منتشر می‌کنند.","Unethical or inappropriate websites; sites that publish content contrary to a community's ethical standards or laws.","مواقع غير أخلاقية أو غير ملائمة؛ مواقع تنشر محتوى يخالف المعايير الأخلاقية أو قوانين المجتمع."],
 "تاکسی‌های اینترنتی":["خدمات حمل‌ونقل با خودرو که از طریق برنامه یا وب‌سایت درخواست می‌شوند و مسافر را به راننده متصل می‌کنند.","Ride-hailing services; car transport services requested through an app or website that connect passengers with drivers.","خدمات سيارات الأجرة عبر الإنترنت؛ خدمات نقل تُطلب من تطبيق أو موقع وتربط الركاب بالسائقين."],
 "کساد":["رکود و کاهش رونق در خریدوفروش، تولید یا فعالیت اقتصادی؛ کم‌مشتری و کم‌معامله بودن بازار.","Recession or slump; a decline in trade, production, or economic activity, with reduced demand and transactions.","كساد أو ركود؛ انخفاض النشاط التجاري أو الإنتاج أو الحركة الاقتصادية مع تراجع الطلب والمعاملات."],
 "گرایش":["تمایل یا علاقهٔ فرد به یک موضوع، رفتار، رشته یا شیوهٔ فکری؛ همچنین جهت‌گیری عمومی.","A tendency, inclination, or orientation toward a subject, behaviour, field, or way of thinking.","ميل أو توجّه نحو موضوع أو سلوك أو مجال أو طريقة تفكير؛ ويعني أيضاً اتجاهاً عاماً."],
 "نویسندهٔ اثر":["فردی که یک کتاب، مقاله، داستان یا اثر هنری یا علمی را پدید آورده است.","The author or creator of a work; the person who produced a book, article, story, or artistic or scholarly work.","مؤلف العمل أو مبدعه؛ الشخص الذي أنشأ كتاباً أو مقالاً أو قصة أو عملاً فنياً أو علمياً."],
 "سست شدن":["از استحکام، نیرو یا پایداری کاسته شدن؛ ضعیف‌تر یا شل‌تر شدن.","To become loose, weak, or less firm; to lose strength, stability, or firmness.","ارتخى أو ضعف؛ فقدَ شيئاً من القوة أو الثبات أو التماسك."],
 "اعتقادات":["باورها و عقایدی که فرد یا گروه دربارهٔ جهان، دین، اخلاق یا موضوع‌های دیگر درست می‌داند.","Beliefs or convictions; ideas that a person or group accepts as true about the world, religion, ethics, or other matters.","المعتقدات؛ أفكار يؤمن بها شخص أو جماعة ويرونها صحيحة بشأن العالم أو الدين أو الأخلاق أو غيرها."],
 "اجرای درست":["انجام دادن یک دستور، برنامه یا روش مطابق با هدف، قواعد و مراحل تعیین‌شده.","Correct implementation or proper execution; carrying out an instruction, plan, or method according to its purpose, rules, and steps.","التنفيذ الصحيح؛ تطبيق تعليمات أو خطة أو طريقة وفق هدفها وقواعدها وخطواتها المحدّدة."],
 "مرور کردن":["مطالعه یا بررسی دوبارهٔ مطلبی برای یادآوری، فهم بهتر یا یافتن اشتباه‌ها.","To review or go over something again to remember it, understand it better, or identify mistakes.","راجعَ أو استعرضَ؛ أعاد دراسة أمر أو فحصه للتذكّر أو تحسين الفهم أو اكتشاف الأخطاء."],
 "نوع نگاه و تفکر":["شیوه‌ای که فرد با آن به موضوع‌ها می‌نگرد، آن‌ها را تفسیر می‌کند و درباره‌شان می‌اندیشد.","A way of looking at and thinking about things; a person's perspective and approach to interpreting issues.","طريقة النظر والتفكير؛ منظور الشخص وأسلوبه في تفسير القضايا والتأمّل فيها."],
 "متن انتقادی":["نوشته‌ای که یک اثر، نظر یا وضعیت را بررسی و ارزیابی می‌کند و نقاط قوت و ضعف آن را بیان می‌سازد.","A critical text or review; writing that examines and evaluates a work, opinion, or situation and discusses its strengths and weaknesses.","نص نقدي؛ كتابة تفحص عملاً أو رأياً أو وضعاً وتقيّمه وتعرض نقاط قوته وضعفه."],
 "ترغیب شدن":["به انجام کاری علاقه‌مند یا متمایل شدن، معمولاً بر اثر تشویق، دلیل یا تأثیر دیگران.","To be encouraged or motivated; to become inclined to do something because of encouragement, reasons, or others' influence.","تشجّعَ أو تحفّزَ؛ أصبح ميّالاً إلى فعل شيء بسبب التشجيع أو الحجج أو تأثير الآخرين."],
 "قاره":["یکی از خشکی‌های بسیار بزرگ زمین که از نظر جغرافیایی منطقه‌ای گسترده و متمایز به شمار می‌رود.","A continent; one of Earth's major continuous landmasses, recognised as a broad geographical region.","قارة؛ إحدى الكتل الأرضية الكبرى على سطح الأرض، وتُعدّ منطقة جغرافية واسعة ومتميّزة."],
 "وعدهٔ غذایی":["یک نوبت مشخص خوردن غذا در روز، مانند صبحانه، ناهار یا شام.","A meal; a regular eating occasion during the day, such as breakfast, lunch, or dinner.","وجبة طعام؛ موعد محدّد لتناول الطعام خلال اليوم، مثل الإفطار أو الغداء أو العشاء."],
 "جدول مقایسه‌ای":["جدولی که ویژگی‌ها یا اطلاعات چند مورد را کنار هم قرار می‌دهد تا شباهت‌ها و تفاوت‌های آن‌ها روشن شود.","A comparison table; a table that places the features or information of several items side by side to show similarities and differences.","جدول مقارنة؛ جدول يعرض خصائص أو معلومات عدة أشياء جنباً إلى جنب لإظهار أوجه الشبه والاختلاف."],
 "پشت سرهم":["به ترتیب و بدون فاصلهٔ زیاد یا وقفه؛ یکی پس از دیگری.","One after another or consecutively; in sequence with little or no gap.","واحداً تلو الآخر أو على التوالي؛ بتتابع ومن دون فاصل كبير أو انقطاع."],
 "جمع‌بندی":["خلاصه کردن نکته‌های اصلی یک بحث یا متن و کنار هم قرار دادن نتیجه‌های آن.","A summary or synthesis; bringing together the main points and conclusions of a discussion or text.","خلاصة أو تركيب؛ جمع النقاط الرئيسية لبحث أو نصّ وضمّ نتائجه بعضها إلى بعض."],
 "نکات ویرایشی":["موارد و پیشنهادهایی که برای اصلاح زبان، املا، نشانه‌گذاری، ساختار و خوانایی یک متن مطرح می‌شوند.","Editing points; issues and suggestions concerning the language, spelling, punctuation, structure, and readability of a text.","ملاحظات تحريرية؛ مسائل واقتراحات تتعلق باللغة والإملاء وعلامات الترقيم والبنية وسهولة قراءة النص."],
 "مقدمه‌چینی":["آماده‌سازی زمینه و بیان نکته‌های آغازین برای ورود به موضوع اصلی؛ گاهی با طولانی کردن غیرضروری مقدمه.","Setting the stage or providing an introduction before the main subject; sometimes an unnecessarily lengthy preamble.","التمهيد؛ إعداد السياق وذكر النقاط الأولية قبل الدخول في الموضوع الرئيسي، وقد يعني أحياناً مقدمة مطوّلة بلا حاجة."],
 "بندبازی":["هنر یا نمایش حرکت و حفظ تعادل روی طناب یا بند کشیده‌شده در ارتفاع.","Tightrope walking; the art or performance of moving and balancing on a rope stretched above the ground.","المشي على الحبل؛ فن أو عرض الحركة والمحافظة على التوازن فوق حبل مشدود على ارتفاع."],
 "تحویل سال":["لحظهٔ آغاز سال نو در تقویم؛ در ایران معمولاً زمان دقیق اعتدال بهاری و آغاز نوروز.","The New Year transition; the exact moment the new year begins in a calendar, in Iran usually at the spring equinox and Nowruz.","لحظة حلول السنة الجديدة؛ وفي إيران توافق عادةً الاعتدال الربيعي وبداية عيد النوروز."],
 "آذین‌بندی":["تزئین کردن مکان، خیابان یا وسیله با چراغ، پرچم، گل یا وسایل زیبا برای جشن و مناسبت.","Decorating or festooning; adorning a place, street, or object with lights, flags, flowers, or ornaments for a celebration.","التزيين؛ تزيين مكان أو شارع أو شيء بالأضواء أو الأعلام أو الأزهار أو الزخارف احتفالاً بمناسبة."],
 "محدودیت":["قید یا مانعی که دامنهٔ آزادی، انتخاب، فعالیت یا دسترسی را کاهش می‌دهد.","A limitation or restriction; a condition that reduces the range of freedom, choice, activity, or access.","قيد أو تقييد؛ شرط يحدّ من نطاق الحرية أو الاختيار أو النشاط أو إمكانية الوصول."],
 "شبکهٔ اینترنت":["مجموعهٔ جهانی از شبکه‌های رایانه‌ای متصل به هم که امکان تبادل اطلاعات و ارتباطات را فراهم می‌کند.","The internet network; the worldwide system of interconnected computer networks that enables communication and information exchange.","شبكة الإنترنت؛ النظام العالمي من شبكات الحاسوب المترابطة الذي يتيح الاتصال وتبادل المعلومات."],
 "سیستم آموزشی":["مجموعهٔ نهادها، برنامه‌ها، روش‌ها و مقرراتی که آموزش و یادگیری را در یک جامعه سازمان‌دهی می‌کند.","An education system; the institutions, programmes, methods, and rules that organise teaching and learning in a society.","النظام التعليمي؛ مجموعة المؤسسات والبرامج والأساليب والقواعد التي تنظّم التعليم والتعلّم في المجتمع."],
 };
 for(const [fa,v] of Object.entries(rows)) S[fa]={...(S[fa]||{}),faMeaning:v[0],enMeaning:v[1],arMeaning:v[2],faSynonyms:(S[fa]||{}).faSynonyms||[],enSynonyms:(S[fa]||{}).enSynonyms||[],arSynonyms:(S[fa]||{}).arSynonyms||[]};
 window.TERM3_ADDITIONAL_SEMANTICS_BATCH31=Object.keys(rows);
})();

/* Term 03 additional vocabulary — semantic batch 32. */
(()=> {
 const S=window.PERSIAN_SEMANTICS||(window.PERSIAN_SEMANTICS={});
 const rows={
 "نظم و آراستگی":["مرتب و منظم بودن ظاهر، وسایل یا محیط و قرار گرفتن هر چیز در جای مناسب خود.","Order and neatness; keeping one's appearance, belongings, or surroundings tidy and well organised.","النظام والترتيب؛ المحافظة على المظهر أو الأغراض أو المكان منظّماً ووضع كل شيء في موضعه المناسب."],
 "صمیمانه":["با گرمی، مهربانی و صداقت؛ به شیوه‌ای دوستانه و بی‌تکلف.","Sincerely or warmly; in a friendly, genuine, and heartfelt manner.","بصدق وودّ؛ بطريقة ودّية وصادقة ومليئة بالمحبة."],
 "مورد اعتماد":["کسی یا چیزی که می‌توان به صداقت، امنیت یا عملکرد آن اطمینان کرد.","Trustworthy or reliable; deserving confidence in one's honesty, safety, or performance.","موثوق أو جدير بالثقة؛ يستحق الاطمئنان إلى صدقه أو أمانه أو أدائه."],
 "احساس و هیجان":["حالت‌های عاطفی و درونی مانند شادی، ترس، اندوه، خشم یا شوق که بر تجربه و رفتار فرد اثر می‌گذارند.","Feelings and emotions; inner states such as joy, fear, sadness, anger, or excitement that influence experience and behaviour.","المشاعر والانفعالات؛ حالات داخلية مثل الفرح والخوف والحزن والغضب والحماس تؤثّر في تجربة الشخص وسلوكه."],
 "زبان شیرین":["شیوهٔ سخن گفتن دلنشین، مهربان و خوشایند؛ همچنین زبانی که برای شنونده جذاب و خوش‌آهنگ است.","Sweet or pleasant language; a warm, kind, and appealing way of speaking.","لغة عذبة أو كلام لطيف؛ أسلوب حديث محبّب وودود وممتع للسامع."],
 "موضوع نوشته":["اندیشه یا مسئلهٔ اصلی که یک متن دربارهٔ آن نوشته شده است.","The subject or topic of a piece of writing; the main idea or issue discussed in a text.","موضوع النص أو الكتابة؛ الفكرة أو المسألة الرئيسية التي يتناولها النص."],
 "امکان تقسیم":["قابلیت یا فرصت بخش‌بندی کردن یک چیز یا مجموعه به قسمت‌های جداگانه.","The possibility of division; the ability or opportunity to separate something into distinct parts.","إمكانية التقسيم؛ القدرة أو الفرصة على تجزئة شيء أو مجموعة إلى أقسام منفصلة."],
 "مراکز اطلاع‌رسانی":["سازمان‌ها یا مکان‌هایی که اطلاعات، راهنمایی و خبر را در اختیار مردم قرار می‌دهند.","Information centres; organisations or places that provide the public with information, guidance, and news.","مراكز المعلومات؛ مؤسسات أو أماكن توفّر للجمهور المعلومات والإرشادات والأخبار."],
 "ولایت فقیه":["نظریه‌ای در فقه سیاسی شیعه دربارهٔ صلاحیت فقیه واجد شرایط برای سرپرستی یا رهبری جامعه در دوران غیبت امام معصوم.","Wilayat al-Faqih; a concept in Shi'a political jurisprudence concerning the authority of a qualified Islamic jurist to oversee or lead the community during the occultation of the infallible Imam.","ولاية الفقيه؛ نظرية في الفقه السياسي الشيعي تتعلّق بصلاحية الفقيه المستوفي للشروط لتولّي الإشراف أو القيادة في المجتمع خلال غيبة الإمام المعصوم."],
 "بیت‌المقدس":["نامی برای شهر اورشلیم یا قدس، به‌ویژه در متون دینی و تاریخی.","Bayt al-Maqdis; a name for Jerusalem or al-Quds, especially in religious and historical texts.","بيت المقدس؛ اسم لمدينة أورشليم أو القدس، ولا سيّما في النصوص الدينية والتاريخية."],
 "سؤال‌های فرعی":["پرسش‌های کوچک‌تر و جزئی‌تری که برای پاسخ دادن به پرسش اصلی یا بررسی دقیق‌تر موضوع مطرح می‌شوند.","Sub-questions; smaller, more specific questions used to answer a main question or examine a topic in greater detail.","الأسئلة الفرعية؛ أسئلة أصغر وأكثر تحديداً تُطرح للإجابة عن السؤال الرئيسي أو دراسة الموضوع بتفصيل أكبر."],
 "هدف و ضرورت نوشتن":["مقصود از نوشتن یک متن و دلیلی که نشان می‌دهد چرا نگارش آن لازم یا مفید است.","The purpose and rationale for writing; the intended aim of a text and the reason it is necessary or useful to write it.","هدف الكتابة وضرورتها؛ الغاية المقصودة من النص والسبب الذي يجعل كتابته لازمة أو مفيدة."],
 "ارزیدن":["ارزش داشتن یا شایسته بودن در برابر هزینه، زمان، تلاش یا توجهی که صرف آن می‌شود.","To be worth something; to have sufficient value to justify the time, effort, cost, or attention spent.","استحقّ أو كان جديراً؛ امتلك قيمة تبرّر الوقت أو الجهد أو المال أو الاهتمام المبذول فيه."],
 "تورفتگی در ماشین":["فرورفتگی یا گودی روی بدنهٔ خودرو که معمولاً بر اثر ضربه یا فشار ایجاد می‌شود.","A dent in a car; an inward depression in the vehicle's bodywork, usually caused by an impact or pressure.","انبعاج في السيارة؛ انخفاض أو تقوّس إلى الداخل في هيكل المركبة يحدث عادةً بسبب صدمة أو ضغط."],
 "کثیف بودن":["تمیز نبودن و داشتن آلودگی، لکه یا گردوغبار.","To be dirty; to have dirt, stains, or dust and not be clean.","كان متّسخاً؛ احتوى على أوساخ أو بقع أو غبار ولم يكن نظيفاً."],
 "به‌یاد ماندن":["در حافظه باقی ماندن و پس از گذشت زمان فراموش نشدن.","To be remembered; to remain in someone's memory and not be forgotten over time.","بقيَ في الذاكرة؛ ظلّ محفوظاً في ذهن الشخص ولم يُنسَ مع مرور الوقت."],
 "باعث آلودگی هوا":["عاملی که با وارد کردن دود، گاز یا ذرات زیان‌آور به جو موجب آلوده شدن هوا می‌شود.","A cause of air pollution; a factor that contaminates the atmosphere by releasing harmful smoke, gases, or particles.","سبب لتلوث الهواء؛ عامل يلوّث الجو بإطلاق دخان أو غازات أو جسيمات ضارة."],
 "ماشین‌های سنگین":["وسایل نقلیهٔ بزرگ و پرقدرت مانند کامیون، اتوبوس و ماشین‌آلات راه‌سازی که برای حمل بار یا کارهای سنگین به کار می‌روند.","Heavy vehicles or heavy machinery, such as trucks, buses, and construction equipment, used for transporting loads or demanding work.","المركبات الثقيلة أو الآليات الكبيرة مثل الشاحنات والحافلات ومعدات البناء، وتُستعمل لنقل الحمولات أو الأعمال الشاقة."],
 "عیب داشتن موتور":["وجود نقص یا خرابی در موتور وسیلهٔ نقلیه یا دستگاه که عملکرد درست آن را مختل می‌کند.","For an engine to have a fault or defect that interferes with its proper operation.","وجود عطل أو خلل في محرّك مركبة أو جهاز يؤثّر في عمله بصورة صحيحة."],
 "پرواز خوب و راحت":["سفری هوایی که با آرامش، ایمنی و بدون مشکل یا ناراحتی قابل توجه انجام شود.","A smooth and comfortable flight; air travel completed safely and pleasantly without significant problems or discomfort.","رحلة جوية مريحة وسلسة؛ سفر بالطائرة يتمّ بأمان وراحة ومن دون مشكلات أو إزعاج ملحوظ."],
 "سوئیچ":["کلید یا وسیله‌ای برای روشن و خاموش کردن دستگاه یا خودرو؛ در خودرو معمولاً به کلید راه‌اندازی موتور گفته می‌شود.","A switch or ignition key; a device for turning equipment on or off, or the key used to start a vehicle.","مفتاح أو قاطع؛ أداة لتشغيل جهاز أو إيقافه، ويُقصد به في السيارة غالباً مفتاح تشغيل المحرّك."],
 "به حساب پول ریختن":["مبلغی را به حساب بانکی شخص یا نهادی واریز کردن.","To deposit or transfer money into a bank account.","أودعَ مبلغاً أو حوّله إلى حساب مصرفي."],
 "از پله‌ها افتادن":["هنگام بالا یا پایین رفتن از پله‌ها تعادل را از دست دادن و سقوط کردن.","To fall down the stairs after losing one's balance while going up or down.","سقطَ على الدرج بعد أن فقد توازنه أثناء الصعود أو النزول."],
 "شکمو":["کسی که علاقهٔ زیادی به خوردن دارد یا بیش از اندازه غذا می‌خورد؛ واژه‌ای محاوره‌ای.","Gluttonous or fond of food; an informal word for someone who enjoys eating a lot or overeats.","شرِه أو محبّ للطعام؛ لفظ محادثي لشخص يحب الأكل كثيراً أو يفرط فيه."],
 "با محبت":["با مهربانی، دلسوزی و توجه به احساسات و نیازهای دیگران.","Affectionately or lovingly; with kindness, care, and consideration for others' feelings and needs.","بمحبة وحنان؛ بلطف ورعاية ومراعاة مشاعر الآخرين واحتياجاتهم."],
 "روغن‌های جامد":["روغن‌ها و چربی‌هایی که در دمای معمول اتاق حالت جامد یا نیمه‌جامد دارند.","Solid fats or oils; fats that are solid or semi-solid at ordinary room temperature.","الزيوت والدهون الصلبة؛ دهون تكون صلبة أو شبه صلبة في درجة حرارة الغرفة العادية."],
 "روغن‌های حیوانی":["چربی‌ها یا روغن‌هایی که از بافت یا فرآورده‌های حیوانی به دست می‌آیند.","Animal fats; fats or oils obtained from animal tissues or products.","الدهون الحيوانية؛ دهون أو زيوت تُستخرج من أنسجة الحيوانات أو منتجاتها."],
 "مصرف سبزیجات":["خوردن و استفاده از سبزی‌ها به عنوان بخشی از رژیم غذایی.","Vegetable consumption; eating and using vegetables as part of one's diet.","استهلاك الخضروات؛ تناول الخضار واستعمالها جزءاً من النظام الغذائي."],
 "عادت‌های غذایی خوب":["رفتارهای تغذیه‌ای سالم و متعادل، مانند خوردن غذای متنوع، رعایت اندازهٔ وعده‌ها و مصرف کافی سبزی و میوه.","Good eating habits; healthy, balanced food behaviours such as eating a varied diet, appropriate portions, and enough vegetables and fruit.","العادات الغذائية الجيدة؛ سلوكيات غذائية صحية ومتوازنة مثل تنويع الطعام وضبط الحصص وتناول كمية كافية من الخضروات والفواكه."],
 "عادت‌های غذایی بد":["رفتارهای تغذیه‌ای ناسالم، مانند پرخوری مداوم، حذف وعده‌ها یا مصرف بیش از اندازهٔ خوراکی‌های کم‌ارزش.","Poor eating habits; unhealthy food behaviours such as frequent overeating, skipping meals, or excessive consumption of low-nutrient foods.","العادات الغذائية السيئة؛ سلوكيات غير صحية مثل الإفراط المتكرر في الأكل أو ترك الوجبات أو تناول أطعمة قليلة القيمة الغذائية بكثرة."],
 };
 for(const [fa,v] of Object.entries(rows)) S[fa]={...(S[fa]||{}),faMeaning:v[0],enMeaning:v[1],arMeaning:v[2],faSynonyms:(S[fa]||{}).faSynonyms||[],enSynonyms:(S[fa]||{}).enSynonyms||[],arSynonyms:(S[fa]||{}).arSynonyms||[]};
 window.TERM3_ADDITIONAL_SEMANTICS_BATCH32=Object.keys(rows);
})();

/* Term 03 additional vocabulary — semantic batch 33. */
(()=> {
 const S=window.PERSIAN_SEMANTICS||(window.PERSIAN_SEMANTICS={});
 const rows={
 "صنعتی شدن":["فرایند گسترش کارخانه‌ها، تولید ماشینی و فعالیت‌های صنعتی در یک جامعه یا منطقه.","Industrialisation; the process of expanding factories, machine-based production, and industrial activity in a society or region.","التصنيع؛ عملية توسّع المصانع والإنتاج الآلي والأنشطة الصناعية في مجتمع أو منطقة."],
 "داغ شدن":["گرم شدن چیزی تا دمای بالا؛ همچنین در گفتار به معنی پرحرارت یا پرتنش شدن بحث و موقعیت.","To become hot; figuratively, for a discussion or situation to become heated or intense.","سخنَ أو أصبح ساخناً؛ ويُستعمل مجازاً لاشتداد النقاش أو الموقف وتوتّره."],
 "سرخ شدن":["به رنگ قرمز درآمدن؛ همچنین دربارهٔ غذا به معنی پختن یا برشته شدن در روغن یا حرارت.","To turn red; for food, to fry or brown through cooking in oil or heat.","احمرّ؛ ويعني عن الطعام قُليَ أو اكتسب لوناً محمّراً بفعل الزيت أو الحرارة."],
 "غذای تند":["خوراکی که به دلیل استفاده از فلفل یا ادویه‌های تند، مزه‌ای تیز و سوزاننده دارد.","Spicy food; food with a sharp, hot taste from chilli peppers or pungent spices.","طعام حارّ؛ طعام له مذاق لاذع أو حار بسبب الفلفل أو التوابل القوية."],
 "رستوران مخصوص":["رستورانی که در تهیه و ارائهٔ نوع خاصی از غذا یا خدمت غذایی تخصص دارد.","A specialised restaurant; an establishment focused on preparing and serving a particular type of food or dining service.","مطعم متخصص؛ مطعم يركّز على إعداد وتقديم نوع معيّن من الطعام أو خدمة غذائية خاصة."],
 "مناسب بودن":["با شرایط، نیاز یا هدفی هماهنگ و سازگار بودن.","To be suitable or appropriate; to fit particular conditions, needs, or purposes.","كان مناسباً أو ملائماً؛ توافقَ مع ظروف أو احتياجات أو أهداف معيّنة."],
 "حوصله نداشتن":["احساس بی‌میلی یا کمبود انرژی روانی برای انجام کاری یا روبه‌رو شدن با موضوعی.","To not feel like doing something; to lack the patience, inclination, or mental energy for an activity.","لم تكن لديه رغبة أو طاقة نفسية؛ افتقر إلى الصبر أو الميل للقيام بنشاط ما."],
 "سرو غذا":["ارائه و آوردن غذا برای مهمانان یا مشتریان تا آن را بخورند.","Serving food; bringing and presenting a meal to guests or customers for them to eat.","تقديم الطعام؛ إحضار الوجبة وعرضها على الضيوف أو الزبائن لتناولها."],
 "خیال آسوده":["احساس آرامش و اطمینان به دلیل نبود نگرانی یا خطر مهم.","Peace of mind; a feeling of calm and reassurance because there is no significant worry or danger.","راحة البال؛ شعور بالطمأنينة والهدوء بسبب غياب القلق أو الخطر المهم."],
 "از یاد رفتن":["فراموش شدن و دیگر در حافظه یا توجه فرد باقی نماندن.","To be forgotten; to fade from someone's memory or attention.","نُسيَ؛ زال من ذاكرة الشخص أو انتباهه ولم يعد يتذكّره."],
 "شماره اشتراک":["شناسه‌ای عددی که برای تشخیص یک مشترک در خدماتی مانند تلفن، آب، برق یا رسانه اختصاص داده می‌شود.","A subscriber number; a numerical identifier assigned to a customer of services such as telephone, water, electricity, or media.","رقم الاشتراك؛ معرّف رقمي يُخصّص لمشترك في خدمات مثل الهاتف أو الماء أو الكهرباء أو الإعلام."],
 "تعمیر جزیی":["رفع یک خرابی کوچک یا انجام اصلاح محدود روی وسیله یا ساختمان، بدون تعمیر اساسی.","A minor repair; fixing a small fault or making a limited adjustment to equipment or a building.","إصلاح بسيط؛ معالجة عطل صغير أو إجراء تعديل محدود على جهاز أو مبنى من دون إصلاح شامل."],
 "کارت اعتباری":["کارتی که برای پرداخت خریدها با استفاده از اعتبار مالی صادرکننده به کار می‌رود و مبلغ آن معمولاً بعداً بازپرداخت می‌شود.","A credit card; a payment card that lets the holder borrow funds from the issuer and repay the amount later.","بطاقة ائتمان؛ بطاقة دفع تتيح لحاملها استخدام رصيد ائتماني من الجهة المصدرة ثم سداده لاحقاً."],
 "شیک":["آراسته، خوش‌پوش و دارای ظاهر زیبا و امروزی؛ همچنین دربارهٔ طراحی یا سبک.","Chic or stylish; neat, fashionable, and attractive in appearance or design.","أنيق أو عصري؛ حسن المظهر ومرتّب وذو تصميم جذّاب."],
 "دل‌انگیز":["بسیار دلپذیر و خوشایند، به‌گونه‌ای که احساس شادی، آرامش یا تحسین ایجاد کند.","Delightful or charming; so pleasant that it creates happiness, calm, or admiration.","آسر أو بهيج؛ ممتع للغاية ويبعث على الفرح أو الراحة أو الإعجاب."],
 "نگران بودن":["احساس اضطراب یا دلواپسی دربارهٔ یک وضعیت، شخص یا نتیجهٔ احتمالی داشتن.","To be worried or concerned about a situation, person, or possible outcome.","كان قلقاً أو مهموماً بشأن حالة أو شخص أو نتيجة محتملة."],
 "مرحلهٔ نهایی":["آخرین بخش یا گام از یک فرایند، مسابقه، برنامه یا پروژه.","The final stage or phase; the last part or step of a process, competition, programme, or project.","المرحلة النهائية؛ الجزء أو الخطوة الأخيرة من عملية أو مسابقة أو برنامج أو مشروع."],
 "عوض شدن":["تغییر کردن یا جای خود را به چیز یا وضعیت دیگری دادن.","To change or be replaced by something or a different condition.","تغيّرَ أو استُبدلَ؛ انتقل إلى حالة أخرى أو حلّ شيء آخر محلّه."],
 "به نظرم":["عبارتی برای بیان نظر یا برداشت شخصی گوینده؛ یعنی از دید من یا به عقیدهٔ من.","In my opinion or it seems to me; an expression introducing the speaker's personal view.","في رأيي أو يبدو لي؛ عبارة لتقديم وجهة نظر المتكلّم الشخصية."],
 "زرنگ بودن":["باهوش و سریع‌الانتقال بودن و توانایی پیدا کردن راه‌حل یا استفاده از فرصت‌ها را داشتن.","To be clever or quick-witted; able to find solutions or make good use of opportunities.","كان ذكياً أو فطناً؛ سريع البديهة وقادراً على إيجاد الحلول أو الاستفادة من الفرص."],
 "پیش آمدن":["رخ دادن یا اتفاق افتادن یک رویداد یا وضعیت، گاهی به شکل غیرمنتظره.","To occur or come up; for an event or situation to happen, sometimes unexpectedly.","حدثَ أو طرأ؛ وقعَ أمر أو موقف، وأحياناً بصورة غير متوقّعة."],
 "فرصت داشتن":["زمان یا امکان کافی برای انجام کاری یا استفاده از موقعیتی در اختیار داشتن.","To have time or an opportunity available to do something or take advantage of a situation.","كان لديه وقت أو فرصة؛ امتلك وقتاً أو إمكانية كافية لإنجاز أمر أو الاستفادة من موقف."],
 "طبق قوانین":["بر اساس قانون‌ها و مقررات تعیین‌شده و با رعایت آن‌ها.","According to the rules or laws; in compliance with the established regulations.","وفقاً للقوانين والأنظمة؛ بما يتوافق مع القواعد المقرّرة ويلتزم بها."],
 "قطعی اینترنت":["از دست رفتن یا متوقف شدن اتصال به اینترنت برای مدتی.","An internet outage or disconnection; a temporary loss or interruption of internet access.","انقطاع الإنترنت؛ فقدان الاتصال بالشبكة أو توقّفه لفترة من الزمن."],
 "بی‌تقصیر":["فاقد مسئولیت یا گناه در رخ دادن یک اشتباه یا مشکل؛ کسی که مقصر نیست.","Innocent or not at fault; not responsible for a mistake or problem.","بريء أو غير مسؤول؛ لا يتحمّل ذنباً أو مسؤولية عن خطأ أو مشكلة."],
 "تولیدی":["مربوط به تولید کالا یا محصول؛ همچنین کارگاه یا کارخانه‌ای که چیزی را تولید می‌کند.","Production-related or manufacturing; also a workshop or factory that makes goods.","إنتاجي أو تصنيعي؛ ويُطلق أيضاً على ورشة أو مصنع ينتج السلع."],
 "ناموفق بودن":["به نتیجه یا هدف مورد نظر نرسیدن و موفق نشدن در انجام کاری.","To be unsuccessful; to fail to achieve the intended result or goal.","لم ينجح؛ لم يتمكّن من بلوغ النتيجة أو الهدف المقصود."],
 "حراج زمستانه":["فروش ویژه‌ای در فصل زمستان که کالاها با قیمت کمتر یا شرایط تخفیفی عرضه می‌شوند.","A winter sale; a seasonal promotion offering goods at reduced prices during winter.","تخفيضات شتوية؛ حملة بيع موسمية تُعرض فيها السلع بأسعار أقل خلال الشتاء."],
 "حراج تابستانه":["فروش ویژه‌ای در فصل تابستان که کالاها با قیمت کمتر یا شرایط تخفیفی عرضه می‌شوند.","A summer sale; a seasonal promotion offering goods at reduced prices during summer.","تخفيضات صيفية؛ حملة بيع موسمية تُعرض فيها السلع بأسعار أقل خلال الصيف."],
 "حراج پاییزه":["فروش ویژه‌ای در فصل پاییز که کالاها با قیمت کمتر یا شرایط تخفیفی عرضه می‌شوند.","An autumn or fall sale; a seasonal promotion offering goods at reduced prices during autumn.","تخفيضات خريفية؛ حملة بيع موسمية تُعرض فيها السلع بأسعار أقل خلال الخريف."],
 };
 for(const [fa,v] of Object.entries(rows)) S[fa]={...(S[fa]||{}),faMeaning:v[0],enMeaning:v[1],arMeaning:v[2],faSynonyms:(S[fa]||{}).faSynonyms||[],enSynonyms:(S[fa]||{}).enSynonyms||[],arSynonyms:(S[fa]||{}).arSynonyms||[]};
 window.TERM3_ADDITIONAL_SEMANTICS_BATCH33=Object.keys(rows);
})();

/* Term 03 additional vocabulary — semantic batch 34. */
(()=> {
 const S=window.PERSIAN_SEMANTICS||(window.PERSIAN_SEMANTICS={});
 const rows={
 "حراج بهاره":["فروش ویژه‌ای در فصل بهار که کالاها با قیمت کاهش‌یافته یا شرایط تخفیفی عرضه می‌شوند.","A spring sale; a seasonal promotion offering goods at reduced prices during spring.","تخفيضات ربيعية؛ حملة بيع موسمية تُعرض فيها السلع بأسعار مخفّضة خلال الربيع."],
 "طول کشیدن":["بیش از زمان معمول یا مورد انتظار ادامه یافتن یک کار یا رویداد.","To take a long time or last longer than expected.","استغرق وقتاً طويلاً؛ استمرّ عمل أو حدث مدة أطول من المعتاد أو المتوقّع."],
 "شرکت در مصاحبه":["حضور و پاسخ‌گویی در گفت‌وگویی رسمی برای ارزیابی فرد، معمولاً هنگام استخدام یا پذیرش.","To attend or take part in an interview, usually a formal conversation used for assessment in hiring or admissions.","شارك في مقابلة؛ حضر حواراً رسمياً للتقييم، غالباً عند التوظيف أو القبول."],
 "بی‌نظیر":["بسیار خاص و ممتاز؛ چیزی که نمونه یا همانندی برای آن به‌سختی پیدا می‌شود.","Unique or unparalleled; exceptionally special or excellent, with few or no equals.","فريد أو لا مثيل له؛ متميّز للغاية ويصعب العثور على ما يساويه."],
 "میل به خرید":["احساس علاقه یا تمایل به خریدن کالا یا خدمتی مشخص.","A desire or inclination to buy; the feeling of wanting to purchase a particular product or service.","الرغبة في الشراء؛ شعور بالميل إلى اقتناء سلعة أو خدمة معيّنة."],
 "جنبه‌های مثبت":["ویژگی‌ها یا بخش‌های خوب و سودمند یک موضوع، تصمیم یا وضعیت.","Positive aspects; the beneficial or favourable features of a subject, decision, or situation.","الجوانب الإيجابية؛ الخصائص أو الأجزاء الجيدة والنافعة في موضوع أو قرار أو حالة."],
 "جنبه‌های منفی":["ویژگی‌ها یا بخش‌های نامطلوب و زیان‌آور یک موضوع، تصمیم یا وضعیت.","Negative aspects; the undesirable or harmful features of a subject, decision, or situation.","الجوانب السلبية؛ الخصائص أو الأجزاء غير المرغوبة أو الضارة في موضوع أو قرار أو حالة."],
 "اتفاق خوشایند":["رویدادی خوب و دلپذیر که موجب شادی، رضایت یا احساس مثبت می‌شود.","A pleasant event; something agreeable that brings happiness, satisfaction, or positive feelings.","حدث سارّ؛ أمر لطيف يبعث على الفرح أو الرضا أو المشاعر الإيجابية."],
 "اتفاق ناخوشایند":["رویدادی نامطلوب که باعث ناراحتی، نگرانی یا احساس ناخوشایند می‌شود.","An unpleasant event; something undesirable that causes distress, worry, or discomfort.","حدث غير سارّ؛ أمر غير مرغوب يسبّب الضيق أو القلق أو عدم الارتياح."],
 "خورجین الاغ‌ها":["کیسه‌ها یا باربندهای جفتی که بر پشت الاغ قرار می‌گیرند و برای حمل بار استفاده می‌شوند.","Donkey panniers or saddlebags; paired bags placed over a donkey's back to carry loads.","أكياس أو خرج توضع على جانبي ظهر الحمار لحمل الأمتعة والبضائع."],
 "به خود پیچیدن":["از شدت درد، ناراحتی یا هیجان بدن را پیچ‌وتاب دادن و آرام و قرار نداشتن.","To writhe or twist about because of intense pain, distress, or emotion.","تلوّى أو تقلبَ؛ حرّك جسمه والتوى من شدّة الألم أو الضيق أو الانفعال."],
 "چاق و چله":["دارای بدن پُر و درشت؛ عبارتی محاوره‌ای برای فردی نسبتاً چاق و تنومند.","Plump and chubby; an informal expression describing someone with a full, sturdy build.","بدين وممتلئ؛ تعبير محادثي لوصف شخص ذي جسم ممتلئ وقوي البنية."],
 "سکته کردن":["دچار سکتهٔ مغزی یا قلبی شدن؛ رخ دادن اختلال ناگهانی در خون‌رسانی مغز یا عملکرد قلب.","To suffer a stroke or heart attack; to experience a sudden disruption affecting the brain's blood supply or the heart.","أُصيبَ بسكتة دماغية أو قلبية؛ حدث اضطراب مفاجئ في تروية الدماغ أو وظيفة القلب."],
 "هموطن":["فردی که با شخص دیگری از یک کشور و تابعیت مشترک است.","A compatriot or fellow countryman; someone who shares the same country or nationality.","مواطن أو ابن وطن؛ شخص يشترك مع غيره في البلد أو الجنسية."],
 "قصد داشتن":["نیت یا تصمیم انجام کاری را داشتن و در فکر انجام آن بودن.","To intend or plan to do something; to have an intention or decision to act.","نوى أو قصدَ فعل شيء؛ كانت لديه نية أو خطة للقيام به."],
 "بستگی داشتن":["وابسته بودن نتیجه یا وضعیت چیزی به عامل، شرط یا موضوع دیگری.","To depend on or be contingent on another factor, condition, or matter.","اعتمدَ على أمر آخر؛ توقّفَت نتيجة أو حالة شيء على عامل أو شرط آخر."],
 "رشد صنعتی":["افزایش و گسترش فعالیت‌های کارخانه‌ای، تولید صنعتی و ظرفیت بخش صنعت در یک منطقه یا کشور.","Industrial growth; the expansion of factories, industrial production, and the capacity of the industrial sector in a region or country.","النمو الصناعي؛ توسّع المصانع والإنتاج الصناعي وقدرات القطاع الصناعي في منطقة أو دولة."],
 "کارواش":["محل یا دستگاهی که برای شستن و تمیز کردن خودرو استفاده می‌شود.","A car wash; a place or machine used to wash and clean vehicles.","مغسلة سيارات؛ مكان أو جهاز يُستعمل لغسل المركبات وتنظيفها."],
 "شلنگ":["لوله‌ای انعطاف‌پذیر که برای انتقال آب، هوا یا مایعات دیگر به کار می‌رود.","A hose; a flexible tube used to carry water, air, or other liquids.","خرطوم؛ أنبوب مرن يُستعمل لنقل الماء أو الهواء أو سوائل أخرى."],
 "عقب انداختن":["انجام کاری را به زمان دیرتری موکول کردن و باعث تأخیر آن شدن.","To postpone or put something off until a later time.","أجّلَ أو أخّرَ؛ نقل موعد عمل إلى وقت لاحق."],
 "کاشتن":["بذر یا نهال را در خاک قرار دادن تا رشد کند و گیاه یا محصولی به وجود آید.","To plant or sow; to put seeds or young plants into soil so they can grow.","زرعَ أو غرسَ؛ وضع بذور أو شتلات في التربة لتنمو وتنتج نباتاً أو محصولاً."],
 "دراز کشیدن":["بدن را در حالت افقی روی تخت، زمین یا سطحی دیگر قرار دادن.","To lie down or stretch out horizontally on a bed, floor, or other surface.","استلقى؛ وضع جسمه أفقياً على سرير أو أرض أو سطح آخر."],
 "برداشت محصول":["جمع‌آوری محصول کشاورزی از زمین یا درخت پس از رسیدن آن.","Harvesting a crop; gathering agricultural produce from fields or trees after it has ripened.","حصاد المحصول؛ جمع المنتجات الزراعية من الأرض أو الأشجار بعد نضجها."],
 "دفن شدن":["در خاک قرار داده شدن و با خاک پوشانده شدن؛ معمولاً دربارهٔ پیکر فرد درگذشته.","To be buried; to be placed in the ground and covered with soil, usually referring to a deceased person.","دُفنَ؛ وُضع في الأرض وغُطّي بالتراب، ويُقال غالباً عن جثمان المتوفّى."],
 "بریدگی":["زخم یا شکافی که بر اثر بریدن یا برخورد جسم تیز روی پوست یا ماده‌ای ایجاد می‌شود.","A cut or incision; a wound or split caused by a sharp object.","جرح أو قطع؛ شقّ أو إصابة تحدث في الجلد أو مادة ما بسبب جسم حاد."],
 "تفاله":["باقی‌ماندهٔ مواد پس از گرفتن آب یا عصارهٔ آن‌ها؛ مانند تفالهٔ میوه، چای یا قهوه.","Pulp or residue; the material left after juice or extract has been removed, such as fruit, tea, or coffee residue.","تفلة أو بقايا؛ المادة المتبقية بعد استخراج العصير أو الخلاصة، مثل بقايا الفاكهة أو الشاي أو القهوة."],
 "ته‌مانده":["مقدار کمی از چیزی که پس از مصرف یا استفاده باقی می‌ماند.","Leftover or remainder; a small amount of something remaining after it has been used or consumed.","بقيّة أو فضلة؛ كمية قليلة تبقى من شيء بعد استعماله أو استهلاكه."],
 "نوک":["بخش انتهایی و باریک چیزی؛ مانند نوک مداد، منقار پرنده یا سر یک ابزار.","The tip or point of something, such as a pencil tip, a bird's beak, or the end of a tool.","طرف أو رأس شيء؛ مثل سنّ القلم أو منقار الطائر أو نهاية أداة."],
 "پنجه":["بخش انتهایی پای جانور که انگشتان و ناخن‌ها یا چنگال‌ها را در بر می‌گیرد؛ همچنین دست یا انگشتان در برخی کاربردها.","A paw or clawed foot; the end of an animal's leg containing its toes and claws; also a hand-like part in some uses.","مخلب أو كفّ الحيوان؛ نهاية رجل الحيوان التي تضم الأصابع والأظافر أو المخالب، ويأتي أحياناً بمعنى الكفّ."],
 "دندان نیش":["یکی از دندان‌های نوک‌تیز در دو سوی دندان‌های پیشین که برای گرفتن و پاره کردن غذا به کار می‌رود.","A canine tooth or fang; a pointed tooth beside the incisors used for gripping and tearing food.","الناب؛ سنّ مدبّب يقع بجانب القواطع ويُستعمل للإمساك بالطعام وتمزيقه."],
 };
 for(const [fa,v] of Object.entries(rows)) S[fa]={...(S[fa]||{}),faMeaning:v[0],enMeaning:v[1],arMeaning:v[2],faSynonyms:(S[fa]||{}).faSynonyms||[],enSynonyms:(S[fa]||{}).enSynonyms||[],arSynonyms:(S[fa]||{}).arSynonyms||[]};
 window.TERM3_ADDITIONAL_SEMANTICS_BATCH34=Object.keys(rows);
})();

/* Term 03 additional vocabulary — semantic batch 35. */
(()=> {
 const S=window.PERSIAN_SEMANTICS||(window.PERSIAN_SEMANTICS={});
 const rows={
 "تکه‌پاره":["به چند بخش یا قطعهٔ جدا و نامنظم پاره‌شده؛ خرد و ازهم‌گسیخته.","Torn into pieces or fragments; broken or ripped into separate, irregular parts.","ممزّق إلى قطع أو أجزاء منفصلة وغير منتظمة؛ متقطّع ومفكّك."],
 "آدم‌خوار":["فرد یا جانوری که گوشت انسان را می‌خورد؛ واژه‌ای برای توصیف رفتار آدم‌خواری.","A cannibal; a person or animal that eats human flesh.","آكل لحوم البشر؛ شخص أو حيوان يأكل لحم الإنسان."],
 "خرطوم":["بخش کشیده و لوله‌مانند بینی و دهان فیل که برای تنفس، بو کشیدن و گرفتن اشیا به کار می‌رود.","A trunk; the long, flexible nose of an elephant used for breathing, smelling, and grasping objects.","خرطوم الفيل؛ أنفه الطويل المرن الذي يستعمله للتنفّس والشمّ والإمساك بالأشياء."],
 "خون‌سردی":["توانایی حفظ آرامش و کنترل احساسات در موقعیت‌های دشوار یا خطرناک.","Composure or cool-headedness; the ability to remain calm and control emotions in difficult or dangerous situations.","رباطة الجأش أو هدوء الأعصاب؛ القدرة على الحفاظ على الهدوء وضبط المشاعر في المواقف الصعبة أو الخطرة."],
 "چاله":["گودی یا حفره‌ای در زمین یا سطح جاده که پایین‌تر از اطراف خود قرار دارد.","A hole, pit, or pothole; a depression in the ground or road surface.","حفرة أو انخفاض في الأرض أو سطح الطريق يكون أدنى من المنطقة المحيطة به."],
 "مشکوک":["چیزی یا کسی که دربارهٔ درستی، صداقت یا بی‌خطری او تردید وجود دارد.","Suspicious or doubtful; someone or something whose honesty, correctness, or safety is questioned.","مريب أو مشكوك فيه؛ شخص أو شيء يُشكّ في صدقه أو صحته أو سلامته."],
 "درپوش":["قطعه‌ای که روی دهانهٔ ظرف یا دستگاه قرار می‌گیرد تا آن را ببندد و از ورود یا خروج چیزی جلوگیری کند.","A lid, cap, or cover placed over an opening to close it and prevent something from entering or escaping.","غطاء أو سدادة توضع على فتحة وعاء أو جهاز لإغلاقها ومنع دخول شيء أو خروجه."],
 "آجری":["ساخته‌شده از آجر یا دارای رنگ و ظاهر شبیه آجر.","Brick-built or brick-coloured; made of bricks or resembling their colour and appearance.","مبنيّ بالطوب أو بلون الطوب؛ مصنوع من الآجر أو يشبه لونه ومظهره."],
 "رژه":["حرکت منظم و هماهنگ گروهی از افراد، معمولاً نیروهای نظامی، در یک مسیر برای نمایش نظم و آمادگی.","A parade or march; the organised, coordinated movement of a group, often military personnel, along a route.","عرض أو مسير؛ حركة منظّمة ومتناسقة لمجموعة من الأشخاص، وغالباً للعسكريين، في طريق لإظهار الانضباط والاستعداد."],
 "وارونه":["برعکس و در جهت یا وضعیتی مخالف حالت معمول یا درست.","Upside down or reversed; in an orientation or condition opposite to the usual or correct one.","مقلوب أو معكوس؛ في اتجاه أو وضع يخالف الحالة المعتادة أو الصحيحة."],
 "فروپاشی":["از هم گسیختن و نابود شدن ساختار، نظام یا مجموعه‌ای که پیش‌تر یکپارچه بوده است.","Collapse or disintegration; the breakdown of a structure, system, or organisation that was previously whole.","انهيار أو تفكّك؛ تحطّم بنية أو نظام أو مؤسسة كانت متماسكة من قبل."],
 "جنگ داخلی":["درگیری مسلحانه میان گروه‌ها یا طرف‌های مختلف در داخل یک کشور.","A civil war; an armed conflict between different groups or factions within one country.","حرب أهلية؛ نزاع مسلّح بين جماعات أو أطراف مختلفة داخل بلد واحد."],
 "حرفه":["کار یا فعالیت تخصصی که فرد با آموزش و مهارت انجام می‌دهد و معمولاً منبع درآمد اوست.","A profession or occupation; specialised work performed with training and skill, usually as a source of income.","مهنة أو حرفة؛ عمل متخصص يؤديه الشخص بالتدريب والمهارة ويكون عادةً مصدر دخله."],
 "مذهب":["نظامی از باورها و آیین‌های دینی؛ همچنین شاخه یا مکتبی درون یک دین.","Religion, denomination, or school of thought; a system of religious beliefs and practices or a branch within a religion.","مذهب أو طائفة أو مدرسة فكرية؛ نظام من المعتقدات والطقوس الدينية أو فرع داخل دين."],
 "بین‌النهرین":["منطقهٔ تاریخی میان رودهای دجله و فرات که بخش بزرگی از عراق امروزی و پیرامون آن را در بر می‌گیرد.","Mesopotamia; the historical region between the Tigris and Euphrates rivers, covering much of modern Iraq and surrounding areas.","بلاد الرافدين؛ المنطقة التاريخية الواقعة بين نهري دجلة والفرات وتشمل معظم العراق الحالي والمناطق المجاورة."],
 "آزادانه":["بدون اجبار یا محدودیت غیرضروری و با اختیار و آزادی عمل.","Freely; without coercion or unnecessary restriction, with freedom to act or choose.","بحرية؛ من دون إكراه أو قيود غير ضرورية، مع حرية التصرّف أو الاختيار."],
 "خط میخی":["شیوهٔ نوشتاری باستانی که در آن نشانه‌های گوه‌مانند روی لوح‌های گِلی یا سطوح دیگر حک می‌شدند.","Cuneiform; an ancient writing system using wedge-shaped marks impressed on clay tablets or other surfaces.","الكتابة المسمارية؛ نظام كتابة قديم استُخدمت فيه علامات إسفينية تُطبع على الألواح الطينية أو أسطح أخرى."],
 "هخامنشیان":["دودمان پادشاهی ایران باستان که از سدهٔ ششم تا چهارم پیش از میلاد بر امپراتوری بزرگی فرمانروایی کرد.","The Achaemenids; the ancient Persian royal dynasty that ruled a vast empire from the sixth to the fourth century BCE.","الأخمينيون؛ السلالة الملكية الفارسية القديمة التي حكمت إمبراطورية واسعة من القرن السادس إلى الرابع قبل الميلاد."],
 "حاصلخیز":["دارای خاک یا شرایطی مناسب برای رشد گیاهان و تولید محصولات کشاورزی.","Fertile or productive; having soil or conditions suitable for plant growth and agricultural production.","خصب أو منتج؛ يمتلك تربة أو ظروفاً مناسبة لنمو النباتات والإنتاج الزراعي."],
 "معابد":["ساختمان‌ها یا مکان‌هایی که برای عبادت و اجرای آیین‌های دینی به کار می‌روند.","Temples; buildings or places used for worship and religious ceremonies.","المعابد؛ مبانٍ أو أماكن تُستخدم للعبادة وإقامة الطقوس الدينية."],
 "رواج داشتن":["در میان مردم یا در یک جامعه معمول و متداول بودن و کاربرد یا پذیرش گسترده داشتن.","To be prevalent or widespread; to be common and widely used or accepted in a community.","كان شائعاً أو رائجاً؛ انتشر استعماله أو قبوله بين الناس أو في المجتمع."],
 "مردم‌شناسی":["دانش مطالعهٔ انسان‌ها و جوامع، فرهنگ‌ها، آداب و شیوه‌های زندگی آنان.","Anthropology; the study of human beings, societies, cultures, customs, and ways of life.","علم الإنسان أو الأنثروبولوجيا؛ دراسة البشر والمجتمعات والثقافات والعادات وأنماط الحياة."],
 "ناخواسته":["بدون قصد یا ارادهٔ قبلی؛ اتفاقی و غیرعمدی.","Unintentionally or unwillingly; without prior intention or deliberate choice.","من دون قصد أو إرادة مسبقة؛ بصورة غير متعمّدة أو غير مقصودة."],
 "نژادپرست":["کسی که بر اساس نژاد یا تبار، افراد را برتر یا فروتر می‌داند یا با آنان تبعیض‌آمیز رفتار می‌کند.","A racist; someone who considers people superior or inferior based on race or ancestry, or treats them discriminatorily.","عنصري؛ شخص يرى الناس أعلى أو أدنى بسبب العرق أو الأصل، أو يعاملهم بتمييز."],
 "محکوم کردن":["در دادگاه کسی را مجرم شناختن و برای او حکم صادر کردن؛ همچنین به شدت نکوهش کردن یک رفتار یا عمل.","To convict or sentence someone in court; also, to condemn an action or behaviour strongly.","أدانَ أو حكمَ على شخص قضائياً؛ ويعني أيضاً استنكار فعل أو سلوك بشدة."],
 "موکول شدن":["انجام یا تصمیم‌گیری دربارهٔ کاری به زمان آینده یا به شخص و مرجع دیگری واگذار شدن.","To be postponed or entrusted; for an action or decision to be deferred to a later time or assigned to another person or authority.","أُرجئَ أو أُوكلَ؛ أُحيل تنفيذ أمر أو اتخاذ قرار إلى وقت لاحق أو إلى شخص أو جهة أخرى."],
 "مبتلا بودن":["به بیماری، مشکل یا وضعیتی ناخوشایند دچار بودن و از آن رنج بردن.","To suffer from or be afflicted with an illness, problem, or difficult condition.","كان مصاباً أو مبتلى؛ عانى من مرض أو مشكلة أو حالة صعبة."],
 "هدفمند":["دارای هدف روشن و برنامه‌ریزی‌شده؛ کاری که با قصد و جهت مشخص انجام می‌شود.","Purposeful or goal-oriented; having a clear objective and being carried out with intention and direction.","هادف؛ ذو غاية واضحة ومخطّط لها، ويُنجز بقصد واتجاه محدّد."],
 "متحرک":["قابل حرکت یا دارای حرکت؛ ثابت و بی‌جنبش نبودن.","Mobile or moving; capable of movement or not fixed in one place.","متحرّك؛ قابل للحركة أو في حالة حركة، وليس ثابتاً في مكانه."],
 "تدفین":["فرایند به خاک سپردن پیکر فرد درگذشته، معمولاً همراه با مراسم و آیین‌های مربوط.","Burial or interment; the act of placing a deceased person's body in the ground, often with related rites.","الدفن؛ عملية مواراة جثمان المتوفّى في التراب، وغالباً ما ترافقها مراسم وطقوس."],
 };
 for(const [fa,v] of Object.entries(rows)) S[fa]={...(S[fa]||{}),faMeaning:v[0],enMeaning:v[1],arMeaning:v[2],faSynonyms:(S[fa]||{}).faSynonyms||[],enSynonyms:(S[fa]||{}).enSynonyms||[],arSynonyms:(S[fa]||{}).arSynonyms||[]};
 window.TERM3_ADDITIONAL_SEMANTICS_BATCH35=Object.keys(rows);
})();

/* Term 03 additional vocabulary — semantic batch 36. */
(()=> {
 const S=window.PERSIAN_SEMANTICS||(window.PERSIAN_SEMANTICS={});
 const rows={
 "سرگرمی":["فعالیتی که برای لذت، تفریح و گذراندن اوقات فراغت انجام می‌شود.","Entertainment or pastime; an activity done for enjoyment, recreation, or leisure.","تسلية أو هواية؛ نشاط يُمارس للمتعة والترفيه وقضاء وقت الفراغ."],
 "شکستن رکورد":["بهتر کردن نتیجهٔ قبلی یا عبور از بالاترین حد ثبت‌شده در یک رقابت یا فعالیت.","To break a record; to surpass the best previously recorded result in a competition or activity.","حطّم رقماً قياسياً؛ تجاوز أفضل نتيجة مسجّلة سابقاً في منافسة أو نشاط."],
 "بیزار بودن":["احساس نفرت یا دلزدگی شدید نسبت به شخص، رفتار یا چیزی داشتن.","To detest or be repulsed by someone or something; to feel strong dislike or aversion.","مقتَ أو نفرَ من شخص أو شيء؛ شعر بنفور أو كراهية شديدة."],
 "مفصل":["دارای جزئیات فراوان و توضیح کامل؛ همچنین محل اتصال دو استخوان در بدن.","Detailed or extensive; containing much information. Also, a joint where two bones meet.","مفصّل أو وافٍ؛ يحتوي على تفاصيل كثيرة. ويعني أيضاً مفصلاً في الجسم حيث تلتقي عظمتان."],
 "کشتار":["کشتن شمار زیادی از انسان‌ها یا جانوران؛ قتل‌عام یا نابودی گسترده.","Mass killing or slaughter; the killing of a large number of people or animals.","مذبحة أو قتل جماعي؛ قتل عدد كبير من البشر أو الحيوانات."],
 "پرطرفدار":["مورد علاقه و استقبال افراد زیادی قرار گرفته و محبوب باشد.","Popular or widely favoured; liked or supported by many people.","شائع أو محبوب؛ يحظى بإعجاب أو تأييد عدد كبير من الناس."],
 "رو در رو":["در مقابل یکدیگر و بدون واسطه قرار داشتن؛ همچنین گفت‌وگوی مستقیم و حضوری.","Face to face; positioned opposite one another or communicating directly in person.","وجهاً لوجه؛ في مواجهة مباشرة أو في تواصل حضوري من دون وسيط."],
 "فواید":["نتیجه‌ها یا ویژگی‌های سودمند و مثبتی که از چیزی به دست می‌آید.","Benefits or advantages; useful and positive results or qualities gained from something.","فوائد أو منافع؛ نتائج أو خصائص إيجابية ونافعة تُكتسب من شيء."],
 "تمام و کامل":["به صورت کامل و بی‌نقص، به گونه‌ای که هیچ بخش یا مرحله‌ای باقی نمانده باشد.","Completely and fully; with nothing missing or left unfinished.","تماماً وبالكامل؛ من دون نقص أو جزء أو مرحلة غير منجزة."],
 "با این حساب":["با توجه به اطلاعات یا شرایط گفته‌شده؛ بنابراین و در نتیجهٔ آن.","Given that or therefore; considering the information or circumstances just mentioned.","بناءً على ذلك أو إذن؛ بالنظر إلى المعلومات أو الظروف المذكورة."],
 "مضطرب":["دچار نگرانی، آشفتگی یا بی‌قراری ذهنی و عاطفی بودن.","Anxious or agitated; experiencing worry, emotional disturbance, or restlessness.","قلق أو مضطرب؛ يعاني من التوتر أو الاضطراب العاطفي أو عدم الاستقرار."],
 "تکان خوردن":["از جای خود حرکت کردن یا بر اثر نیرو، ضربه یا لرزش جابه‌جا شدن.","To move, shake, or be displaced from one's position because of force, impact, or vibration.","تحرّكَ أو اهتزّ؛ انتقل من موضعه بفعل قوة أو ضربة أو اهتزاز."],
 "کابل":["سیم یا مجموعه‌ای از رشته‌های محافظت‌شده برای انتقال برق، داده یا پیام؛ همچنین نام پایتخت افغانستان.","A cable; a protected wire or bundle of wires used to transmit electricity, data, or signals. Also, Kabul, the capital of Afghanistan.","كابل؛ سلك أو مجموعة أسلاك معزولة لنقل الكهرباء أو البيانات أو الإشارات. ويعني أيضاً كابول عاصمة أفغانستان."],
 "تزیین":["زیباتر کردن چیزی با افزودن نقش، رنگ، گل، چراغ یا وسایل آراسته.","Decoration or embellishment; making something more attractive by adding patterns, colours, flowers, lights, or ornaments.","التزيين؛ تحسين مظهر شيء بإضافة نقوش أو ألوان أو أزهار أو أضواء أو زينة."],
 "خوش‌یمن":["در باور یا برداشت مردم نشانهٔ خوشبختی، موفقیت یا رخداد خوب دانسته شود.","Auspicious or lucky; regarded as a sign of good fortune, success, or a favourable event.","ميمون أو مبارك؛ يُعدّ علامة على الحظ الجيد أو النجاح أو حدث حسن."],
 "اعم از":["شاملِ همهٔ موارد گفته‌شده بودن، چه یک مورد و چه موردهای دیگر؛ بدون محدود شدن به یکی از آن‌ها.","Including or whether; covering all the stated cases without being limited to just one of them.","بما في ذلك؛ يشمل الحالات المذكورة ولا يقتصر على حالة واحدة منها."],
 "حنابندان":["مراسمی سنتی پیش از عروسی در برخی فرهنگ‌ها که در آن دست‌وپای عروس و گاهی داماد را با حنا رنگ می‌کنند.","Henna night or henna ceremony; a traditional pre-wedding event in some cultures when the bride, and sometimes the groom, has henna applied to hands and feet.","ليلة الحناء؛ احتفال تقليدي قبل الزفاف في بعض الثقافات توضع فيه الحناء على يدي العروس وقدميها وأحياناً العريس."],
 "امامزاده":["آرامگاه یا زیارتگاه منسوب به یکی از فرزندان یا نوادگان امامان شیعه.","An Imamzadeh shrine; a tomb or pilgrimage site attributed to a child or descendant of a Shi'a Imam.","إمام زاده؛ ضريح أو مزار يُنسب إلى أحد أبناء أو أحفاد أئمة الشيعة."],
 "به‌خصوص":["به طور ویژه و مشخص؛ بیش از دیگر موارد یا افراد مورد نظر.","Especially or particularly; in a specific or greater degree than other cases or people.","خصوصاً أو على وجه الخصوص؛ بصورة مميّزة أو بدرجة أكبر من الحالات أو الأشخاص الآخرين."],
 "کف دریا":["بخش پایین یا بستر دریا که زیر آب قرار دارد؛ همچنین سطح پایینی محیط دریایی.","The sea floor or seabed; the bottom surface of the sea beneath the water.","قاع البحر؛ السطح السفلي للبحر الواقع تحت الماء."],
 "یادگاری":["چیزی که برای به یاد آوردن شخص، مکان یا رویدادی نگهداری می‌شود؛ سوغات یا نشانهٔ خاطره.","A keepsake or memento; an item kept to remember a person, place, or event.","تذكار؛ شيء يُحتفظ به لتذكّر شخص أو مكان أو حدث، وقد يعني هدية تذكارية."],
 "بریده":["جداشده یا قطع‌شده از چیزی بزرگ‌تر؛ همچنین بخشی کوتاه که از متن یا روزنامه جدا شده باشد.","Cut off or detached; also, an excerpt or clipping taken from a longer text or publication.","مقطوع أو منفصل؛ ويعني أيضاً مقتطفاً أو قصاصة مأخوذة من نص أو مطبوعة أطول."],
 "برش":["عمل بریدن یا قطعه‌ای که با بریدن از چیزی جدا شده است.","A cut or slice; the act of cutting or a piece separated from something by cutting.","قطع أو شريحة؛ فعل القطع أو قطعة فُصلت من شيء بعملية القطع."],
 "استادکار":["فردی بسیار ماهر و باتجربه در یک حرفهٔ فنی یا دستی که کارهای تخصصی انجام می‌دهد.","A master craftsperson or skilled tradesperson with extensive experience in a technical or manual profession.","حِرَفيّ ماهر أو معلّم صنعة؛ شخص ذو خبرة واسعة في مهنة فنية أو يدوية."],
 "پاک شدن":["از آلودگی، لکه یا ناپاکی رها شدن؛ تمیز و پاکیزه شدن.","To become clean or be cleared of dirt, stains, or impurity.","تطهّر أو تنظّف؛ زالت عنه الأوساخ أو البقع أو النجاسة."],
 "آمیزد":["صورت ادبی و کهن فعل «آمیختن»؛ به معنی مخلوط می‌کند یا درهم می‌آمیزد.","An archaic or literary form of the Persian verb 'to mix'; meaning 'mixes' or 'blends'.","صيغة فارسية أدبية أو قديمة من فعل «مزج»؛ بمعنى يخلط أو يمزج."],
 "غرقه":["فرو رفته یا پوشیده‌شده در آب یا مایع؛ همچنین به طور مجازی غرق در اندیشه یا احساس.","Submerged or immersed; covered by water or another liquid, and figuratively absorbed in thought or emotion.","مغمور أو غارق؛ مغطّى بالماء أو سائل آخر، ويُستعمل مجازاً لمن استغرق في فكرة أو شعور."],
 "خیزد":["صورت ادبی و کهن فعل «خاستن»؛ به معنی برمی‌خیزد یا بلند می‌شود.","An archaic or literary form of the Persian verb 'to rise'; meaning 'rises' or 'gets up'.","صيغة فارسية أدبية أو قديمة من فعل «نهض»؛ بمعنى يقوم أو يرتفع."],
 "درود":["واژه‌ای برای سلام و ابراز احترام و آرزوی خیر برای دیگری.","Greetings or salutations; an expression of respect and goodwill toward another person.","تحية أو سلام؛ لفظ للتعبير عن الاحترام وتمنّي الخير للآخر."],
 "سرشناس":["فردی شناخته‌شده و مشهور که در یک زمینه جایگاه یا اعتبار دارد.","Well-known or prominent; a recognised person with standing or reputation in a particular field.","معروف أو بارز؛ شخص مشهور له مكانة أو سمعة في مجال معيّن."],
 };
 for(const [fa,v] of Object.entries(rows)) S[fa]={...(S[fa]||{}),faMeaning:v[0],enMeaning:v[1],arMeaning:v[2],faSynonyms:(S[fa]||{}).faSynonyms||[],enSynonyms:(S[fa]||{}).enSynonyms||[],arSynonyms:(S[fa]||{}).arSynonyms||[]};
 window.TERM3_ADDITIONAL_SEMANTICS_BATCH36=Object.keys(rows);
})();

/* Term 03 additional vocabulary — semantic batch 37. */
(()=> {
 const S=window.PERSIAN_SEMANTICS||(window.PERSIAN_SEMANTICS={});
 const rows={
 "در نهایت":["در پایان و پس از بررسی یا گذشت مراحل مختلف؛ سرانجام.","Ultimately or finally; at the end, after considering or going through different stages.","في النهاية أو أخيراً؛ بعد النظر في مراحل مختلفة أو المرور بها."],
 "پاداش":["چیزی مانند پول، هدیه یا امتیاز که در برابر کار خوب، تلاش یا موفقیت داده می‌شود.","A reward or bonus given in return for good work, effort, or achievement.","مكافأة أو جائزة تُمنح مقابل عمل حسن أو جهد أو إنجاز."],
 "اسیر":["فردی که در جنگ یا درگیری به دست طرف مقابل گرفتار شده و آزادی او سلب شده است؛ همچنین کسی که در بند چیزی باشد.","A captive or prisoner; someone captured in war or conflict and deprived of freedom, or figuratively held by something.","أسير؛ شخص أُسر في حرب أو نزاع وسُلبت حريته، ويُستعمل مجازاً لمن وقع في أسر شيء."],
 "سفارت‌خانه":["نمایندگی رسمی یک کشور در کشور دیگر که امور دیپلماتیک و کنسولی را انجام می‌دهد.","An embassy; the official diplomatic mission of one country in another, handling diplomatic and consular affairs.","سفارة؛ بعثة دبلوماسية رسمية لدولة في دولة أخرى تتولّى الشؤون الدبلوماسية والقنصلية."],
 "خواجه":["در متون تاریخی، عنوان احترام‌آمیز برای مردی صاحب‌منصب یا صاحب‌مال؛ همچنین در کاربرد تاریخی به مردی که اخته شده است گفته می‌شود.","A khwaja; a historical honorific for a respected or wealthy man or official; historically also an eunuch.","خواجه؛ لقب احترام تاريخي لرجل ذي مكانة أو مال أو منصب، ويُستعمل تاريخياً أيضاً للرجل المخصي."],
 "صاحب دلق":["کسی که دلق، یعنی خرقه یا جامهٔ سادهٔ صوفیانه، می‌پوشد؛ تعبیری ادبی برای درویش یا زاهد.","A wearer of the dervish cloak; a literary expression for a dervish or ascetic who wears a simple Sufi robe.","لابس الدلق؛ تعبير أدبي عن درويش أو زاهد يرتدي خرقة صوفية بسيطة."],
 "خوش‌نوا":["دارای صدای خوش‌آهنگ و دلنشین؛ به‌ویژه دربارهٔ پرنده یا آواز.","Melodious or sweet-sounding; especially describing a bird or a voice or song.","عذب الصوت أو حسن النغم؛ يُقال خصوصاً عن الطيور أو الأصوات والأغاني."],
 "گویا":["ظاهراً و چنان‌که به نظر می‌رسد؛ همچنین به معنی سخنگو و دارای قدرت بیان در برخی کاربردها.","Apparently or seemingly; in another use, eloquent or able to speak.","على ما يبدو أو كأنّ؛ ويأتي في استعمال آخر بمعنى ناطق أو فصيح."],
 "حیران":["دچار شگفتی، سردرگمی یا ناتوانی در تصمیم‌گیری شدن.","Astonished, bewildered, or perplexed; feeling surprise or uncertainty about what to do.","متحيّر أو مندهش؛ يشعر بالدهشة أو الحيرة ولا يعرف كيف يتصرّف."],
 "بانگ":["صدای بلند و رسا، مانند فریاد، ندا یا آوای زنگ.","A loud call or cry; a strong, resonant sound such as a shout, summons, or bell tone.","صوت مرتفع أو نداء؛ صوت قويّ واضح مثل الصرخة أو النداء أو رنين الجرس."],
 "نبشتن":["نوشتن؛ صورت ادبی و کهن فعل «نوشتن» در فارسی.","To write; a literary or archaic Persian form of the verb 'to write'.","كتبَ؛ صيغة فارسية أدبية أو قديمة من فعل الكتابة."],
 "طب کودکان":["شاخه‌ای از پزشکی که به پیشگیری، تشخیص و درمان بیماری‌ها و مراقبت از سلامت نوزادان، کودکان و نوجوانان می‌پردازد.","Paediatrics or pediatrics; the branch of medicine concerned with the health, prevention, diagnosis, and treatment of infants, children, and adolescents.","طب الأطفال؛ فرع من الطب يُعنى بصحة الرضّع والأطفال والمراهقين والوقاية من أمراضهم وتشخيصها وعلاجها."],
 "عضو هیأت":["فردی که به طور رسمی در یک هیأت، شورا، کمیته یا گروه تصمیم‌گیری عضویت دارد.","A board or committee member; a person formally belonging to a panel, council, committee, or decision-making group.","عضو هيئة أو لجنة؛ شخص ينتمي رسمياً إلى مجلس أو هيئة أو لجنة أو مجموعة لاتخاذ القرار."],
 "بر عهده داشتن":["مسئولیت انجام کاری یا پاسخ‌گویی دربارهٔ آن را پذیرفتن و متعهد بودن.","To be responsible for or in charge of a task or duty.","تولّى مسؤولية أمر أو مهمة؛ التزم بإنجازها أو المساءلة عنها."],
 "متأسفانه":["واژه‌ای برای بیان تأسف یا ناراحتی از یک اتفاق یا وضعیت نامطلوب.","Unfortunately; an expression used to show regret or sadness about an undesirable event or situation.","للأسف؛ كلمة تُستعمل للتعبير عن الأسف أو الحزن إزاء حدث أو وضع غير مرغوب."],
 "انتهای خیابان باریک":["بخش پایانی خیابانی کم‌عرض؛ جایی که مسیر آن به پایان می‌رسد.","The end of a narrow street; the final section of a street with limited width.","نهاية شارع ضيّق؛ الجزء الأخير من طريق قليل العرض."],
 "به حساب بانکی ریختن":["پول را به حساب بانکی فرد یا سازمان واریز کردن.","To deposit money into a bank account belonging to a person or organisation.","أودعَ المال في حساب مصرفي لشخص أو مؤسسة."],
 "یک واحد آپارتمان":["یک بخش مستقل از یک ساختمان آپارتمانی که معمولاً شامل فضای زندگی و امکانات اختصاصی است.","An apartment unit; one self-contained residence within an apartment building, usually with its own living space and facilities.","وحدة سكنية في مبنى شقق؛ مسكن مستقل داخل مبنى سكني يضم عادةً مساحة معيشة ومرافق خاصة."],
 "مجتمع آپارتمانی":["مجموعه‌ای از چندین واحد مسکونی در یک یا چند ساختمان که معمولاً امکانات یا فضاهای مشترک دارند.","An apartment complex; a group of residential units in one or more buildings, usually sharing facilities or common areas.","مجمع سكني للشقق؛ مجموعة وحدات سكنية في مبنى أو عدة مبانٍ تشترك عادةً في مرافق أو مساحات عامة."],
 "هزینه‌های نظافت":["مبالغی که برای تمیز کردن و نگهداری پاکیزگی یک ساختمان، محل کار یا فضای مشترک پرداخت می‌شود.","Cleaning expenses; costs paid for cleaning and maintaining the cleanliness of a building, workplace, or shared area.","تكاليف التنظيف؛ مبالغ تُدفع لتنظيف مبنى أو مكان عمل أو مساحة مشتركة والمحافظة على نظافتها."],
 "محوطه":["فضای باز یا محدودهٔ اطراف یک ساختمان، مجموعه یا مکان مشخص.","A grounds or courtyard area; the open space or surrounding area of a building, complex, or specific place.","باحة أو ساحة؛ مساحة مفتوحة أو منطقة تحيط بمبنى أو مجمّع أو مكان محدّد."],
 "راهرو":["مسیر باریک و معمولاً سرپوشیده در داخل ساختمان که اتاق‌ها یا بخش‌های مختلف را به هم متصل می‌کند.","A hallway or corridor; a narrow, usually indoor passage connecting rooms or different parts of a building.","ممر أو رواق؛ ممر ضيق غالباً داخل المبنى يصل بين الغرف أو الأقسام المختلفة."],
 "حسابدار":["فرد متخصص در ثبت، بررسی و گزارش درآمدها، هزینه‌ها و تراکنش‌های مالی یک شخص یا سازمان.","An accountant; a professional who records, examines, and reports the income, expenses, and financial transactions of a person or organisation.","محاسب؛ مختص يسجّل الإيرادات والنفقات والمعاملات المالية لشخص أو مؤسسة ويفحصها ويعدّ تقارير عنها."],
 "قرارداد جدید":["توافق‌نامه‌ای تازه که میان دو یا چند طرف برای تعیین حقوق، تعهدات و شرایط همکاری یا معامله منعقد می‌شود.","A new contract; a recently made agreement between two or more parties setting out rights, obligations, and terms.","عقد جديد؛ اتفاق أُبرم حديثاً بين طرفين أو أكثر لتحديد الحقوق والالتزامات والشروط."],
 "تهیهٔ غذا":["آماده کردن مواد و پخت یا فراهم کردن خوراک برای مصرف.","Food preparation; preparing ingredients and cooking or arranging a meal for consumption.","إعداد الطعام؛ تجهيز المكوّنات وطهي الوجبة أو توفيرها للاستهلاك."],
 "سیاه‌چادر":["خیمهٔ سنتی ساخته‌شده از موی بز سیاه که برخی عشایر و کوچ‌نشینان برای سکونت استفاده می‌کنند.","A black nomadic tent; a traditional tent woven from black goat hair and used as a dwelling by some pastoral nomads.","بيت شعر أسود؛ خيمة تقليدية منسوجة من شعر الماعز الأسود يستعملها بعض البدو والرعاة الرحّل للسكن."],
 "تغییر دادن":["چیزی را از حالت، شکل یا وضعیت پیشین به حالت دیگری درآوردن.","To change or alter something from its previous state, form, or condition.","غيّرَ شيئاً أو بدّله من حالته أو شكله أو وضعه السابق إلى حالة أخرى."],
 "جامعهٔ امروز":["مردم و ساختارهای اجتماعی در زمان حاضر، با ویژگی‌ها و مسائل مربوط به زندگی معاصر.","Today's society; people and social structures in the present era, with the characteristics and issues of contemporary life.","مجتمع اليوم؛ الناس والبُنى الاجتماعية في العصر الحاضر بما يتّصل بالحياة المعاصرة من خصائص وقضايا."],
 "آمار طلاق":["داده‌های عددی دربارهٔ تعداد، میزان یا روند طلاق در یک جامعه یا دورهٔ زمانی.","Divorce statistics; numerical data on the number, rate, or trends of divorce in a society or period.","إحصاءات الطلاق؛ بيانات رقمية حول عدد حالات الطلاق أو معدّلاتها أو اتجاهاتها في مجتمع أو فترة زمنية."],
 "تأثیر روابط اجتماعی":["اثری که ارتباط‌ها و تعامل‌های میان افراد بر افکار، احساسات، رفتار یا وضعیت اجتماعی آنان می‌گذارد.","The influence of social relationships; the effect that interactions among people have on their thoughts, feelings, behaviour, or social circumstances.","تأثير العلاقات الاجتماعية؛ الأثر الذي تتركه تفاعلات الناس في أفكارهم ومشاعرهم وسلوكهم أو أوضاعهم الاجتماعية."],
 };
 for(const [fa,v] of Object.entries(rows)) S[fa]={...(S[fa]||{}),faMeaning:v[0],enMeaning:v[1],arMeaning:v[2],faSynonyms:(S[fa]||{}).faSynonyms||[],enSynonyms:(S[fa]||{}).enSynonyms||[],arSynonyms:(S[fa]||{}).arSynonyms||[]};
 window.TERM3_ADDITIONAL_SEMANTICS_BATCH37=Object.keys(rows);
})();

/* Term 03 additional vocabulary — semantic batch 38. */
(()=> {
 const S=window.PERSIAN_SEMANTICS||(window.PERSIAN_SEMANTICS={});
 const rows={
 "نیازهای روحی و فیزیکی":["نیازهای مربوط به سلامت روان و بدن، مانند آرامش، امنیت عاطفی، غذا، آب، خواب و فعالیت بدنی.","Psychological and physical needs, such as peace of mind, emotional security, food, water, sleep, and physical activity.","الاحتياجات النفسية والجسدية، مثل راحة البال والأمان العاطفي والطعام والماء والنوم والنشاط البدني."],
 "تقویت سلامت":["بهبود یا افزایش توان و وضعیت سلامت جسمی و روانی از راه مراقبت، تغذیه و فعالیت مناسب.","To improve or strengthen health through appropriate care, nutrition, and activity.","تعزيز الصحة؛ تحسين الحالة الصحية الجسدية والنفسية أو تقويتها من خلال الرعاية والتغذية والنشاط المناسب."],
 "تلف کردن وقت":["زمان را بیهوده صرف کردن و آن را بدون رسیدن به هدف مفید از دست دادن.","To waste time; to spend time uselessly without achieving a worthwhile goal.","إضاعة الوقت؛ إنفاق الزمن بلا فائدة ومن دون تحقيق هدف نافع."],
 "دچار بیماری شدن":["به بیماری مبتلا شدن و وضعیت سلامت فرد بر اثر آن مختل شدن.","To fall ill or become sick; to develop an illness that affects one's health.","أُصيب بمرض أو مرضَ؛ ظهرت لديه حالة مرضية أثّرت في صحته."],
 "کاهش دادن":["مقدار، شدت یا اندازهٔ چیزی را کمتر کردن.","To reduce or decrease the amount, intensity, or size of something.","قلّلَ أو خفّضَ مقدار شيء أو شدّته أو حجمه."],
 "بزرگسالان":["افرادی که از دورهٔ کودکی و نوجوانی گذشته‌اند و به سن بزرگسالی رسیده‌اند.","Adults; people who have passed childhood and adolescence and reached adulthood.","البالغون؛ أشخاص تجاوزوا مرحلتي الطفولة والمراهقة ووصلوا إلى سن الرشد."],
 "مشکلات قلبی":["بیماری‌ها یا اختلال‌هایی که ساختار یا عملکرد قلب را تحت تأثیر قرار می‌دهند.","Heart problems or conditions that affect the structure or function of the heart.","مشكلات أو اضطرابات قلبية تؤثّر في بنية القلب أو وظيفته."],
 "دچار شدن":["به وضعیتی، مشکل یا بیماری گرفتار شدن و آن را تجربه کردن.","To become afflicted with or experience a condition, problem, or illness.","ابتُليَ أو وقعَ في حالة أو مشكلة أو مرض وأصبح يعاني منه."],
 "جشن طبیعت":["مراسم یا جشنی برای گرامی‌داشت طبیعت و محیط زیست؛ در ایران می‌تواند به روز طبیعت در سیزدهم فروردین اشاره کند.","A nature celebration; an event honouring nature and the environment. In Iran, it may refer to Nature Day on the thirteenth of Farvardin.","احتفال بالطبيعة؛ مناسبة لتكريم الطبيعة والبيئة، وقد يُقصد بها في إيران يوم الطبيعة في الثالث عشر من فروردين."],
 "کم‌توقع":["کسی که خواسته‌ها و انتظارهای اندکی دارد و به امکانات یا داشته‌های محدود قانع است.","Undemanding or low-maintenance; someone who has few expectations and is content with limited resources or circumstances.","قليل المطالب أو التوقّعات؛ شخص لا يطلب الكثير ويقنع بالإمكانات أو الظروف المحدودة."],
 "فوت کردن":["با بیرون دادن هوا از دهان چیزی را خنک یا خاموش کردن؛ همچنین در زبان محاوره به معنی درگذشتن.","To blow air from the mouth to cool or extinguish something; colloquially, also to pass away.","نفخَ الهواء من الفم لتبريد شيء أو إطفائه؛ ويُستعمل عامياً أيضاً بمعنى توفّي."],
 "کار خیر":["کاری نیک و سودمند که با نیت کمک، مهربانی یا خدمت به دیگران انجام می‌شود.","A good deed; a beneficial act done with the intention of helping or serving others.","عمل خير؛ فعل نافع يُنجز بنية مساعدة الآخرين أو الإحسان إليهم أو خدمتهم."],
 "ممتاز":["بسیار خوب و برجسته؛ دارای کیفیت یا عملکردی بالاتر از حد معمول.","Excellent or outstanding; having quality or performance above the usual level.","ممتاز أو متفوّق؛ ذو جودة أو أداء أعلى من المستوى المعتاد."],
 "خشن":["زبر و ناصاف در لمس؛ همچنین دربارهٔ رفتار یا گفتار به معنی تند، سخت یا نامهربان.","Rough or coarse to the touch; also harsh or severe when describing behaviour or speech.","خشن أو خشن الملمس؛ ويعني عن السلوك أو الكلام الشديد أو القاسي أو غير اللطيف."],
 "مجسمه":["پیکره‌ای سه‌بعدی از انسان، جانور یا شکل دیگری که از سنگ، فلز، چوب، گِل یا مواد دیگر ساخته می‌شود.","A statue or sculpture; a three-dimensional figure of a person, animal, or other form made from stone, metal, wood, clay, or other materials.","تمثال أو منحوتة؛ شكل ثلاثي الأبعاد لإنسان أو حيوان أو هيئة أخرى مصنوع من الحجر أو المعدن أو الخشب أو الطين أو مواد أخرى."],
 "اسکناس":["قطعه‌ای کاغذی یا پلیمری که از سوی بانک مرکزی یا مرجع پولی به عنوان پول رایج منتشر می‌شود.","A banknote or bill; a paper or polymer note issued by a central bank or monetary authority as currency.","ورقة نقدية؛ ورقة من الورق أو البوليمر تصدرها جهة نقدية أو بنك مركزي بوصفها عملة متداولة."],
 "موتور الکتریکی":["دستگاهی که انرژی الکتریکی را به انرژی مکانیکی و حرکت چرخشی یا خطی تبدیل می‌کند.","An electric motor; a device that converts electrical energy into mechanical energy and rotational or linear motion.","محرّك كهربائي؛ جهاز يحوّل الطاقة الكهربائية إلى طاقة ميكانيكية وحركة دورانية أو خطية."],
 "الکتریسیته":["شکل انرژی مرتبط با بارهای الکتریکی که می‌تواند برای روشنایی، گرما و به کار انداختن دستگاه‌ها استفاده شود.","Electricity; a form of energy associated with electric charges, used for lighting, heating, and powering devices.","الكهرباء؛ شكل من أشكال الطاقة المرتبطة بالشحنات الكهربائية ويُستعمل للإضاءة والتدفئة وتشغيل الأجهزة."],
 "خودآموزی":["یادگیری یک موضوع یا مهارت به طور مستقل، بدون حضور دائمی معلم و با استفاده از منابع آموزشی.","Self-study or self-learning; learning a subject or skill independently without continuous instruction from a teacher.","التعلّم الذاتي؛ تعلّم موضوع أو مهارة بصورة مستقلة من دون تعليم مستمر من معلّم وباستخدام مصادر تعليمية."],
 "شیمیدان":["دانشمندی که مواد، ترکیب‌ها، واکنش‌ها و ویژگی‌های شیمیایی آن‌ها را مطالعه می‌کند.","A chemist; a scientist who studies substances, compounds, chemical reactions, and their properties.","كيميائي؛ عالم يدرس المواد والمركّبات والتفاعلات الكيميائية وخصائصها."],
 "کاشف":["فردی که مکان، حقیقت، پدیده یا دانسته‌ای ناشناخته را پیدا و آشکار می‌کند.","A discoverer or explorer; someone who finds and reveals a previously unknown place, fact, or phenomenon.","مكتشف أو مستكشف؛ شخص يعثر على مكان أو حقيقة أو ظاهرة لم تكن معروفة من قبل ويكشفها."],
 "کشف کردن":["چیزی ناشناخته یا پنهان را پیدا کردن و وجود یا حقیقت آن را آشکار ساختن.","To discover; to find something unknown or hidden and reveal its existence or truth.","اكتشفَ؛ عثر على شيء مجهول أو خفيّ وكشف وجوده أو حقيقته."],
 "تغذیه کردن":["به انسان، جانور یا گیاه غذا و مواد لازم برای رشد و ادامهٔ زندگی رساندن.","To feed or nourish a person, animal, or plant by providing food and nutrients needed for growth and life.","غذّى؛ قدّم للإنسان أو الحيوان أو النبات الطعام والمغذّيات اللازمة للنمو واستمرار الحياة."],
 "چاه":["گودالی عمیق که برای دسترسی به آب زیرزمینی، نفت یا منابع دیگر حفر می‌شود.","A well or shaft; a deep hole dug to reach groundwater, oil, or other underground resources.","بئر أو حفرة عميقة تُحفر للوصول إلى المياه الجوفية أو النفط أو موارد أخرى تحت الأرض."],
 "ناپدید شدن":["از دید یا دسترس خارج شدن و دیگر دیده یا پیدا نشدن.","To disappear or vanish; to go out of sight or reach and no longer be seen or found.","اختفى أو توارى؛ خرج من مجال الرؤية أو الوصول ولم يعد يُرى أو يُعثر عليه."],
 "واضح":["روشن و قابل فهم؛ چیزی که ابهام یا پیچیدگی کمی دارد.","Clear or obvious; easy to understand and not ambiguous.","واضح أو جليّ؛ سهل الفهم ولا يكتنفه غموض."],
 "غیرعادی":["خارج از حالت معمول یا انتظار؛ نامتعارف و متفاوت از آنچه بیشتر دیده می‌شود.","Unusual or abnormal; outside what is normal or expected.","غير عادي أو غير مألوف؛ خارج عن الحالة المعتادة أو المتوقّعة."],
 "بادنجان":["گیاهی خوراکی با میوه‌ای معمولاً بنفش و گوشتی که در غذاهای گوناگون پخته می‌شود؛ بادمجان.","Eggplant or aubergine; an edible plant with usually purple, fleshy fruit used in many dishes.","الباذنجان؛ نبات مأكول ثماره لحمية وغالباً بنفسجية اللون ويُطهى في أطباق متنوعة."],
 "خبرچین":["کسی که اطلاعات و خبرهای دیگران را، معمولاً برای آسیب رساندن یا جلب منفعت، به شخص یا نهادی منتقل می‌کند.","An informer or tattletale; someone who passes on information about others, often to cause harm or gain an advantage.","واشٍ أو نمّام؛ شخص ينقل أخبار الآخرين أو معلوماتهم إلى جهة ما، غالباً للإضرار بهم أو لتحقيق منفعة."],
 "تقلیدکار":["کسی که رفتار، گفتار یا سبک دیگران را بدون ابتکار مستقل بازآفرینی می‌کند.","An imitator or copycat; someone who reproduces another person's behaviour, speech, or style without independent originality.","مقلّد؛ شخص يحاكي سلوك الآخرين أو كلامهم أو أسلوبهم من دون ابتكار مستقل."],
 };
 for(const [fa,v] of Object.entries(rows)) S[fa]={...(S[fa]||{}),faMeaning:v[0],enMeaning:v[1],arMeaning:v[2],faSynonyms:(S[fa]||{}).faSynonyms||[],enSynonyms:(S[fa]||{}).enSynonyms||[],arSynonyms:(S[fa]||{}).arSynonyms||[]};
 window.TERM3_ADDITIONAL_SEMANTICS_BATCH38=Object.keys(rows);
})();

/* Term 03 additional vocabulary — semantic batch 39. */
(()=> {
 const S=window.PERSIAN_SEMANTICS||(window.PERSIAN_SEMANTICS={});
 const rows={
 "گیاهخوار":["فردی که در رژیم غذایی خود گوشت و ماهی مصرف نمی‌کند و بیشتر از مواد غذایی گیاهی استفاده می‌کند.","A vegetarian; someone whose diet excludes meat and fish and relies mainly on plant-based foods.","نباتيّ؛ شخص لا يتناول اللحوم والأسماك في نظامه الغذائي ويعتمد أساساً على الأغذية النباتية."],
 "توخالی":["دارای فضای خالی درون خود و بدون مادهٔ پُرکننده در بخش داخلی.","Hollow; having an empty space inside rather than being solid throughout.","أجوف؛ يحتوي على فراغ داخلي وليس مصمتاً بالكامل."],
 "توپر":["دارای بخش داخلی پُر و بدون فضای خالی؛ همچنین در نوشتار به حروف ضخیم گفته می‌شود.","Solid or filled; having no hollow space inside. In typography, also describing bold lettering.","مصمت أو ممتلئ؛ لا يحتوي على فراغ داخلي. ويُستعمل في الطباعة أيضاً لوصف الخط العريض."],
 "مسافت":["فاصلهٔ میان دو نقطه یا مکان که معمولاً با واحدهایی مانند متر و کیلومتر اندازه‌گیری می‌شود.","Distance; the space between two points or places, commonly measured in units such as metres or kilometres.","المسافة؛ البعد بين نقطتين أو مكانين، ويُقاس عادةً بوحدات مثل المتر والكيلومتر."],
 "حیوانات شکاری":["جانورانی که برای به دست آوردن غذا، جانوران دیگر را شکار می‌کنند.","Predatory animals; animals that hunt other animals for food.","الحيوانات المفترسة؛ حيوانات تصطاد حيوانات أخرى للحصول على الغذاء."],
 "ویژگی‌های ظاهری":["خصوصیات قابل مشاهدهٔ چهره یا بدن یک فرد، جانور یا شیء، مانند رنگ، اندازه و شکل.","Physical or outward features; visible characteristics of a person's, animal's, or object's appearance, such as colour, size, and shape.","السمات الظاهرية؛ الخصائص المرئية لوجه أو جسم شخص أو حيوان أو شيء، مثل اللون والحجم والشكل."],
 "گورخر":["جانوری آفریقایی از خانوادهٔ اسب‌سانان که بدن آن با نوارهای سیاه و سفید مشخص می‌شود.","A zebra; an African member of the horse family distinguished by its black-and-white stripes.","الحمار الوحشي؛ حيوان أفريقي من فصيلة الخيليات يتميّز بخطوطه السوداء والبيضاء."],
 "قوچ":["گوسفند نر بالغ که معمولاً شاخ‌های خمیده و بزرگی دارد.","A ram; an adult male sheep, usually with large curved horns.","كبش؛ ذكر الخروف البالغ، وله عادةً قرون كبيرة منحنية."],
 "شترمرغ":["بزرگ‌ترین پرندهٔ زنده که نمی‌تواند پرواز کند و پاهای بلند و توانایی دویدن سریع دارد.","An ostrich; the largest living bird, which cannot fly and has long legs adapted for fast running.","النعامة؛ أكبر الطيور الحية، لا تستطيع الطيران ولها ساقان طويلتان تساعدانها على الركض السريع."],
 "اسکلت":["مجموعهٔ استخوان‌های بدن انسان یا جانور که به بدن شکل می‌دهد و از اندام‌های داخلی محافظت می‌کند.","A skeleton; the framework of bones that gives the body shape and protects internal organs.","الهيكل العظمي؛ مجموعة عظام الجسم التي تمنحه شكله وتحمي أعضاءه الداخلية."],
 "دستگیره":["بخشی از وسیله یا در که برای گرفتن، کشیدن، باز کردن یا کنترل آن استفاده می‌شود.","A handle or knob; the part of an object or door used to grip, pull, open, or control it.","مقبض أو يد؛ جزء من أداة أو باب يُستعمل للإمساك أو السحب أو الفتح أو التحكّم."],
 "پادری":["فرش یا زیرانداز کوچکی که جلوی در قرار می‌گیرد تا کفش‌ها پیش از ورود پاک شوند.","A doormat; a small mat placed at a doorway for wiping shoes before entering.","ممسحة أو دعّاسة الباب؛ بساط صغير يوضع أمام المدخل لمسح الأحذية قبل الدخول."],
 "قدم‌زنان":["در حال راه رفتن و برداشتن قدم‌ها، معمولاً با آرامش و بدون عجله.","Walking or strolling; moving on foot, usually calmly and without hurry.","ماشياً أو متنزّهاً؛ يتحرّك على قدميه غالباً بهدوء ومن دون عجلة."],
 "مستمند":["فردی که از نظر مالی یا امکانات زندگی نیازمند کمک دیگران است.","Needy or indigent; someone who lacks sufficient money or resources for living and needs assistance.","محتاج أو معوز؛ شخص يفتقر إلى المال أو الموارد الكافية للمعيشة ويحتاج إلى المساعدة."],
 "معبد":["ساختمان یا مکانی که پیروان یک دین برای عبادت و برگزاری آیین‌های مذهبی از آن استفاده می‌کنند.","A temple; a building or place used by followers of a religion for worship and religious ceremonies.","معبد؛ مبنى أو مكان يستخدمه أتباع دين للعبادة وإقامة الشعائر الدينية."],
 "صنایع":["مجموعهٔ فعالیت‌های تولیدی و کارخانه‌ای که مواد اولیه را به کالا یا محصولات قابل استفاده تبدیل می‌کنند.","Industries; sectors of production and manufacturing that turn raw materials into usable goods or products.","الصناعات؛ قطاعات الإنتاج والتصنيع التي تحوّل المواد الخام إلى سلع أو منتجات قابلة للاستعمال."],
 "تغییرات سیاسی":["دگرگونی‌ها در ساختار حکومت، سیاست‌ها، قدرت یا روابط سیاسی یک کشور یا جامعه.","Political changes; shifts in a country's or society's government structure, policies, power, or political relationships.","التغيّرات السياسية؛ التحوّلات في بنية الحكم أو السياسات أو السلطة أو العلاقات السياسية في بلد أو مجتمع."],
 "حمل و نقل":["جابه‌جایی افراد یا کالاها از یک مکان به مکان دیگر با وسایلی مانند خودرو، قطار، کشتی یا هواپیما.","Transportation or transport; moving people or goods from one place to another by vehicles, trains, ships, or aircraft.","النقل والمواصلات؛ انتقال الأشخاص أو البضائع من مكان إلى آخر بوسائل مثل السيارات والقطارات والسفن والطائرات."],
 "اعیاد":["روزها یا مناسبت‌های جشن و شادی که معمولاً به دلیل دینی، ملی یا فرهنگی گرامی داشته می‌شوند.","Festivals or holidays; days of celebration observed for religious, national, or cultural reasons.","الأعياد والمناسبات؛ أيام احتفال تُحيى لأسباب دينية أو وطنية أو ثقافية."],
 "توفان":["باد بسیار شدید که گاهی با باران، گردوغبار یا موج‌های بزرگ همراه است و می‌تواند خسارت ایجاد کند.","A storm or tempest; very strong winds, sometimes accompanied by rain, dust, or large waves, that may cause damage.","عاصفة؛ رياح شديدة جداً قد تصحبها أمطار أو غبار أو أمواج كبيرة وقد تسبّب أضراراً."],
 "باتری":["وسیله‌ای که انرژی شیمیایی را به انرژی الکتریکی تبدیل و آن را برای تأمین برق دستگاه‌ها ذخیره می‌کند.","A battery; a device that converts chemical energy into electrical energy and stores it to power equipment.","بطارية؛ جهاز يحوّل الطاقة الكيميائية إلى طاقة كهربائية ويخزّنها لتشغيل الأجهزة."],
 "بلور":["ماده‌ای جامد با ساختار منظم و بلوری؛ همچنین قطعه‌ای شفاف و درخشان از شیشه یا کریستال.","A crystal; a solid with an ordered crystalline structure, or a clear, sparkling piece of crystal glass.","بلّور؛ مادة صلبة ذات بنية بلورية منتظمة، ويُطلق أيضاً على قطعة شفافة لامعة من الكريستال."],
 "نعلبکی":["ظرف کوچک و کم‌عمقی که فنجان یا استکان چای روی آن قرار می‌گیرد.","A saucer; a small, shallow dish on which a teacup or tea glass is placed.","صحن الفنجان؛ طبق صغير وضحل يوضع عليه فنجان القهوة أو كأس الشاي."],
 "غلیظ":["دارای ضخامت یا تراکم زیاد؛ دربارهٔ مایع به معنی پرقوام و کم‌روان.","Thick or dense; having considerable thickness or, for a liquid, a heavy consistency and low flow.","سميك أو كثيف؛ ذو سماكة أو كثافة عالية، ويُقال عن السائل إنه ثقيل القوام قليل السيولة."],
 "تلخ":["دارای مزه‌ای ناخوشایند و غیرشیرین، مانند مزهٔ قهوهٔ بدون شکر؛ همچنین دربارهٔ تجربه به معنی اندوه‌بار.","Bitter; having a sharp, non-sweet taste, or figuratively describing a sorrowful experience.","مُرّ؛ ذو مذاق لاذع غير حلو، ويُستعمل مجازاً لوصف تجربة محزنة."],
 "چایخانه":["مکانی که در آن چای و گاهی نوشیدنی‌ها و خوراکی‌های ساده برای مشتریان سرو می‌شود.","A teahouse or tea shop; a place where tea and sometimes simple drinks and snacks are served.","بيت شاي أو مقهى شاي؛ مكان تُقدّم فيه الشاي وأحياناً مشروبات ومأكولات خفيفة للزبائن."],
 "خانگی":["مربوط به خانه یا کاری که در خانه انجام می‌شود؛ همچنین چیزی که در محیط خانه تهیه شده است.","Homemade or domestic; relating to the home or made or carried out at home.","منزلي أو بيتي؛ متعلق بالمنزل أو مصنوع أو مُنجز في البيت."],
 "لذیذ":["دارای طعم و مزه‌ای بسیار خوشایند و دلپذیر.","Delicious or tasty; having a very pleasant and enjoyable flavour.","لذيذ أو شهيّ؛ ذو مذاق طيّب وممتع للغاية."],
 "سازماندهی":["مرتب و هماهنگ کردن افراد، کارها یا منابع برای رسیدن به هدفی مشخص.","Organisation or organising; arranging and coordinating people, tasks, or resources to achieve a specific goal.","التنظيم؛ ترتيب الأشخاص أو الأعمال أو الموارد وتنسيقها لتحقيق هدف محدّد."],
 "وسایل ارتباط جمعی":["رسانه‌هایی مانند تلویزیون، رادیو، روزنامه و وب‌سایت‌های خبری که پیام و اطلاعات را به شمار زیادی از مردم منتقل می‌کنند.","Mass media; channels such as television, radio, newspapers, and news websites that deliver information to large audiences.","وسائل الإعلام الجماهيري؛ قنوات مثل التلفاز والإذاعة والصحف والمواقع الإخبارية تنقل الرسائل والمعلومات إلى جمهور واسع."],
 };
 for(const [fa,v] of Object.entries(rows)) S[fa]={...(S[fa]||{}),faMeaning:v[0],enMeaning:v[1],arMeaning:v[2],faSynonyms:(S[fa]||{}).faSynonyms||[],enSynonyms:(S[fa]||{}).enSynonyms||[],arSynonyms:(S[fa]||{}).arSynonyms||[]};
 window.TERM3_ADDITIONAL_SEMANTICS_BATCH39=Object.keys(rows);
})();

/* Term 03 additional vocabulary — semantic batch 40. */
(()=> {
 const S=window.PERSIAN_SEMANTICS||(window.PERSIAN_SEMANTICS={});
 const rows={
 "تبلیغ کردن":["کالا، خدمت، اندیشه یا رویدادی را معرفی و ترویج کردن تا توجه و علاقهٔ دیگران به آن جلب شود.","To advertise or promote a product, service, idea, or event to attract people's attention and interest.","أعلنَ أو روّجَ لسلعة أو خدمة أو فكرة أو مناسبة لجذب انتباه الآخرين واهتمامهم."],
 "برون‌مرزی":["مربوط به آن سوی مرزهای یک کشور یا انجام‌شده میان دو یا چند کشور.","Cross-border or transnational; relating to or taking place beyond a country's borders or between countries.","عابر للحدود؛ متعلق بما وراء حدود دولة أو بما يجري بين دولتين أو أكثر."],
 "رقیب":["فرد یا گروهی که برای دستیابی به هدف، موفقیت یا جایگاه مشابه با دیگری رقابت می‌کند.","A competitor or rival; a person or group competing with another for the same goal, success, or position.","منافس أو ندّ؛ شخص أو جماعة تتنافس مع غيرها على هدف أو نجاح أو مكانة مشتركة."],
 "خدمتگزار":["کسی که برای کمک و خدمت به دیگران یا انجام امور یک فرد یا سازمان کار می‌کند.","A servant or attendant; someone who works to assist others or perform duties for a person or organisation.","خادم أو مساعد؛ شخص يعمل لمساعدة الآخرين أو أداء شؤون شخص أو مؤسسة."],
 "بالا زدن":["به سمت بالا حرکت کردن یا از سطحی فراتر آمدن؛ دربارهٔ آب یا مایع به معنی بالا آمدن و سرریز کردن نیز می‌آید.","To rise or come up; for water or liquid, to rise above a level or overflow.","ارتفع أو صعد؛ ويقال عن الماء أو السائل إذا ارتفع فوق مستواه أو فاض."],
 "پشت پا زدن به":["چیزی ارزشمند، تعهد یا فرصتی را با بی‌اعتنایی رد کردن یا کنار گذاشتن.","To spurn or turn one's back on something; to reject or abandon a valuable opportunity, commitment, or principle.","رفضَ أو نبذَ أمراً؛ أعرض عن فرصة أو التزام أو مبدأ ذي قيمة وتخلّى عنه."],
 "آبغوره گرفتن":["از انگور نارس با فشردن آب گرفتن تا برای چاشنی و طعم‌دهی غذا استفاده شود.","To make verjuice by pressing unripe grapes for their sour juice, used as a seasoning.","عصرَ العنب غير الناضج لاستخراج عصيره الحامض المعروف بالفيرجوس، ويُستخدم للتتبيل."],
 "پنبه را از گوش درآوردن":["به طور جدی گوش دادن و توجه کردن؛ کنایه از اینکه کسی از بی‌توجهی دست بردارد.","To pay attention and listen carefully; an idiom urging someone to stop ignoring what is being said.","أصغى وانتبه جيداً؛ تعبير اصطلاحي يُقال لمن يُطلب منه أن يكفّ عن تجاهل الكلام."],
 "جوهر":["مایع رنگی برای نوشتن یا چاپ؛ همچنین در معنای مجازی، اصل و ماهیت درونی یک چیز.","Ink; a coloured liquid used for writing or printing. Figuratively, the essence or inner nature of something.","حبر؛ سائل ملوّن للكتابة أو الطباعة، ويأتي مجازاً بمعنى جوهر الشيء وماهيته الداخلية."],
 "خیس کردن":["چیزی را با آب یا مایع دیگری مرطوب و نمناک کردن.","To wet or soak something with water or another liquid.","بلّلَ شيئاً بالماء أو بسائل آخر وجعله رطباً."],
 "ضد رطوبت":["دارای ویژگی یا پوششی که از نفوذ یا اثر رطوبت جلوگیری می‌کند.","Moisture-resistant or damp-proof; designed to prevent the penetration or effects of moisture.","مقاوم للرطوبة؛ مصمّم لمنع نفاذ الرطوبة أو تأثيرها."],
 "عرق‌گیر":["لباس یا پارچه‌ای که عرق بدن را جذب می‌کند؛ مانند زیرپوش یا نوار پارچه‌ای مخصوص پیشانی و مچ.","A sweat-absorbing garment or sweatband; such as an undershirt or a band worn on the forehead or wrist.","ملابس أو رباط ماصّ للعرق؛ مثل القميص الداخلي أو الشريط القماشي الذي يوضع على الجبهة أو المعصم."],
 "نظامیان":["افرادی که عضو نیروهای مسلح هستند و در ارتش یا سازمان نظامی خدمت می‌کنند.","Military personnel or servicemembers; people who belong to and serve in the armed forces.","العسكريون أو أفراد القوات المسلحة؛ أشخاص ينتمون إلى الجيش أو مؤسسة عسكرية ويخدمون فيها."],
 "اسفنج":["ماده‌ای نرم و متخلخل که آب و مایعات را جذب می‌کند و برای شست‌وشو یا پاک کردن به کار می‌رود.","A sponge; a soft, porous material that absorbs water and liquids and is used for washing or cleaning.","إسفنج؛ مادة لينة مسامية تمتص الماء والسوائل وتُستعمل للغسل أو التنظيف."],
 "آستین":["بخش لباس که بازو را می‌پوشاند و از سرشانه تا مچ یا بخشی از آن امتداد دارد.","A sleeve; the part of a garment that covers the arm from the shoulder toward the wrist.","كُمّ؛ جزء من الثوب يغطي الذراع ويمتد من الكتف باتجاه المعصم."],
 "پوسیده":["فرسوده و از هم‌گسیخته بر اثر گذشت زمان، رطوبت، پوسیدگی یا آسیب.","Rotten or decayed; deteriorated and breaking down because of age, moisture, decay, or damage.","متعفّن أو بالٍ؛ تدهور وتفكّك بسبب مرور الزمن أو الرطوبة أو التعفّن أو التلف."],
 "خنک‌کننده":["وسیله یا ماده‌ای که دما را پایین می‌آورد و چیزی را خنک می‌کند.","A cooler or cooling agent; a device or substance that lowers temperature and makes something cool.","مُبرّد أو مادة تبريد؛ جهاز أو مادة تخفّض درجة الحرارة وتُبرّد شيئاً."],
 "پیمان":["توافق یا تعهد رسمی میان دو یا چند فرد، گروه یا کشور؛ عهد و قرارداد.","A pact, treaty, or agreement; a formal commitment between two or more people, groups, or countries.","عهد أو ميثاق أو اتفاق؛ التزام رسمي بين شخصين أو جماعتين أو دولتين أو أكثر."],
 "شربت":["نوشیدنی شیرینی که معمولاً از آب، شکر و عصاره یا طعم‌دهندهٔ میوه و گیاه تهیه می‌شود؛ همچنین مایع دارویی.","A sweet syrup drink made from water, sugar, and fruit or herbal flavouring; also a medicinal syrup.","شراب حلو يُحضّر عادةً من الماء والسكر وخلاصة الفاكهة أو الأعشاب؛ ويعني أيضاً شراباً دوائياً."],
 "نورباران":["روشن کردن فراوان یک مکان با چراغ‌ها و نورهای متعدد، معمولاً برای جشن یا مناسبت ویژه.","Illuminating a place with many lights, usually for a celebration or special occasion.","إضاءة مكان بكثرة بالمصابيح والأنوار، غالباً احتفالاً بمناسبة خاصة."],
 "منبر":["جایگاه یا سکوی پلکانی در مسجد یا مکان مذهبی که خطیب یا سخنران از آن برای سخن گفتن استفاده می‌کند.","A pulpit; a raised or stepped platform in a mosque or religious venue from which a speaker delivers a sermon or address.","منبر؛ منصة مرتفعة أو مدرّجة في مسجد أو مكان ديني يخطب منها المتحدّث أو الواعظ."],
 "صله رحم":["دیدار، ارتباط و نیکی به خویشاوندان و حفظ پیوندهای خانوادگی؛ از آموزه‌های اخلاقی و دینی اسلام.","Maintaining family ties; visiting, communicating with, and showing kindness to relatives, an important Islamic ethical teaching.","صلة الرحم؛ زيارة الأقارب والتواصل معهم والإحسان إليهم والمحافظة على الروابط العائلية، وهي قيمة أخلاقية إسلامية."],
 "کماج":["نوعی نان یا شیرینی سنتی ایرانی که در برخی مناطق با آرد، شیر، شکر و مواد معطر تهیه می‌شود.","Komaj; a traditional Iranian bread or sweet pastry made in some regions with flour, milk, sugar, and aromatic ingredients.","كُماج؛ نوع من الخبز أو الحلوى التقليدية الإيرانية يُحضّر في بعض المناطق من الدقيق والحليب والسكر ومكوّنات عطرية."],
 "حلوا ارده":["خوراکی شیرین و مقوی که از اردهٔ کنجد و شیرین‌کننده‌هایی مانند شکر یا شیره تهیه می‌شود.","Halva-ardeh; a sweet, energy-rich confection made from sesame paste (tahini) and sweeteners such as sugar or syrup.","حلوى الطحينة؛ حلوى حلوة وغنية بالطاقة تُحضّر من معجون السمسم (الطحينة) ومحليات مثل السكر أو القطر."],
 "هگمتانه":["نام باستانی شهری در ایران که معمولاً با اکباتان و همدان امروزی مرتبط دانسته می‌شود و از مراکز مهم مادها و دوره‌های بعد بود.","Hegmataneh; the ancient city commonly identified with Ecbatana and modern Hamadan in Iran, an important centre under the Medes and later periods.","هگمتانه؛ مدينة إيرانية قديمة تُطابق عادةً أكباتان وهمدان الحالية، وكانت مركزاً مهماً في عهد الميديين والعصور اللاحقة."],
 "پیام‌رسانی":["فرایند فرستادن و دریافت پیام و اطلاعات میان افراد یا گروه‌ها از راه گفتار، نوشتار یا ابزارهای ارتباطی.","Messaging or communication; the process of sending and receiving messages and information between people or groups.","المراسلة أو تبادل الرسائل؛ عملية إرسال المعلومات والرسائل وتلقّيها بين الأفراد أو الجماعات بالكلام أو الكتابة أو وسائل الاتصال."],
 "انگشت‌پیچ":["نوعی شیرینی سنتی و چسبناک ایرانی، به‌ویژه در همدان، که معمولاً از سفیدهٔ تخم‌مرغ و شکر یا شیره تهیه می‌شود.","Angosht-pich; a traditional sticky Iranian sweet, especially associated with Hamadan, commonly made from egg whites and sugar or syrup.","أنغشت بيچ؛ حلوى إيرانية تقليدية لزجة، تشتهر بها همدان، وتُحضّر عادةً من بياض البيض والسكر أو القطر."],
 "شقایق":["گیاهی گل‌دار با گلبرگ‌های ظریف و رنگارنگ، معمولاً قرمز، که در دشت‌ها و مزارع می‌روید.","A poppy; a flowering plant with delicate, often red petals that grows in fields and open areas.","شقائق النعمان أو الخشخاش؛ نبات مزهر ذو بتلات رقيقة وغالباً حمراء، ينمو في الحقول والأماكن المفتوحة."],
 "انسان‌های اولیه":["انسان‌هایی که در دوره‌های بسیار کهن پیش از شکل‌گیری جوامع و تمدن‌های امروزی زندگی می‌کردند.","Early humans or prehistoric people; humans who lived in very ancient periods before modern societies and civilisations developed.","الإنسان القديم أو البشر الأوائل؛ أشخاص عاشوا في عصور سحيقة قبل نشوء المجتمعات والحضارات الحديثة."],
 "غیرمسلح":["فاقد سلاح یا ابزار جنگی؛ بدون سلاح.","Unarmed; not carrying or equipped with weapons.","أعزل؛ لا يحمل سلاحاً ولا يكون مجهّزاً بأسلحة."],
 };
 for(const [fa,v] of Object.entries(rows)) S[fa]={...(S[fa]||{}),faMeaning:v[0],enMeaning:v[1],arMeaning:v[2],faSynonyms:(S[fa]||{}).faSynonyms||[],enSynonyms:(S[fa]||{}).enSynonyms||[],arSynonyms:(S[fa]||{}).arSynonyms||[]};
 window.TERM3_ADDITIONAL_SEMANTICS_BATCH40=Object.keys(rows);
})();
